#!/usr/bin/env python3
"""Dedplay Stüdyo 0.5.60 yaması (0.5.59 üzerine).
  - Günlük sınır yüzünden bekleyen denetim, konteyner yeniden başlarsa kaybolmaz (2 Kasım: Tahrif 1-3 08:05'te sürmedi).
  - Seslendirmeye gönderirken sesi olmayan (tamamı okunmaz) parça EPUB'u düşürmez ("Document is empty").
Tekrar çalıştırılabilir: dosya zaten yeniyse dokunmaz; ne eski ne yeni ise durur."""
import hashlib, os, sys
ESKI = {'kutuphane/depo.py': '0ef1232467a7d7f5c3bd34830e2891a2', 'app/worker.py': '262167e6cdb27d818dda6c48c9017ea4', 'kutuphane/main.py': '76b6ff7d6bc8ced64e89043e1ba2c1e8'}
YENI = {'kutuphane/depo.py': b'"""Kitaplar\xc4\xb1n diskteki d\xc3\xbczeni ve arka plan i\xc5\x9fleri.\n\n/data/kitaplar/<kimlik>/kitap.json   tek kaynak\n/data/kitaplar/<kimlik>/durum.json   i\xc5\x9f durumu, EPUB listesi, denetim sonu\xc3\xa7lar\xc4\xb1\n/data/kitaplar/<kimlik>/kaynak.txt   indirilen as\xc4\xb1l metin (yeniden okumak i\xc3\xa7in)\n/data/kitaplar/<kimlik>/epub/*.epub\n"""\nimport json\nimport os\nimport queue\nimport re\nimport shutil\nimport threading\nimport time\nimport traceback\nimport unicodedata\n\nimport requests\n\nfrom . import epub as EPUB\nfrom . import cikti, epubcheck, kaynak, katalog, openiti, osmanlica, yz\nfrom . import kitap as K\n\nVERI = os.environ.get("DATA_DIR", "/data")\nKITAPLAR = os.path.join(VERI, "kitaplar")\nKIMLIK = re.compile(r"^[A-Za-z0-9._-]{1,120}$")\nDIL_AD = {"ar": "arapca", "en": "ingilizce", "fr": "fransizca", "fa": "farsca"}\n_kuyruk = queue.Queue()  # hafif \xc5\x9ferit (0.5.17): EPUB/DOCX/TXT, katmanl\xc4\xb1 ya da \xc3\xb6nbellekteki PDF, Osmanl\xc4\xb1ca, EPUB i\xc5\x9fleri\n_kuyruk_agir = queue.Queue()  # a\xc4\x9f\xc4\xb1r \xc5\x9ferit: OCR gerektiren PDF\'ler, birer birer (Surya b\xc3\xbct\xc3\xbcn i\xc5\x9flemciyi kullan\xc4\xb1r)\n_is_kilitleri = {}  # ayn\xc4\xb1 kitab\xc4\xb1n iki i\xc5\x9fi ayn\xc4\xb1 anda \xc3\xa7al\xc4\xb1\xc5\x9fmas\xc4\xb1n\n_kilit = threading.Lock()\n_kitap_kilitleri = {}\n_bekleyen_epub = set()  # kuyrukta bekleyen EPUB i\xc5\x9fleri: art arda d\xc3\xbczeltmelerde tek i\xc5\x9f\n# 0.5.19: kuyruktaki kitap silinebilir. Her kitab\xc4\xb1n bir "nesli" var; silinince artar ve kuyrukta kalan eski i\xc5\x9fleri\n# ge\xc3\xa7ersiz olur (ayn\xc4\xb1 kitap yeniden eklenirse yeni nesille \xc3\xa7al\xc4\xb1\xc5\x9f\xc4\xb1r). \xc4\xb0\xc5\x9fi \xc3\xa7al\xc4\xb1\xc5\x9fan kitap "silinecek" diye i\xc5\x9faretlenir:\n# i\xc5\x9f bir sonraki ilerleme bildiriminde durur, sonra kitap silinir.\n_nesil = {}\n_calisan = {}       # \xc5\x9ferit ad\xc4\xb1 -> kitap kimli\xc4\x9fi\n_silinecek = set()\n\n\nclass IsIptal(Exception):\n    pass\n\n\ndef kitap_kilidi(kid):\n    """kitap.json\'u yazan her i\xc5\x9f (arka plan ya da okuma ekran\xc4\xb1) bu kilidi tutar: d\xc3\xbczeltmeler kaybolmaz."""\n    with _kilit:\n        return _kitap_kilitleri.setdefault(kid, threading.Lock())\n\n\ndef klasor(kid):\n    if not KIMLIK.match(kid or ""):\n        raise ValueError("ge\xc3\xa7ersiz kitap kimli\xc4\x9fi")\n    return os.path.join(KITAPLAR, kid)\n\n\ndef durum_oku(kid):\n    yol = os.path.join(klasor(kid), "durum.json")\n    try:\n        return json.load(open(yol, encoding="utf-8"))\n    except (FileNotFoundError, json.JSONDecodeError):\n        return {}\n\n\ndef durum_yaz(kid, **kw):\n    with _kilit:\n        d = durum_oku(kid)\n        d.update(kw)\n        d["guncellendi"] = int(time.time())\n        yol = os.path.join(klasor(kid), "durum.json")\n        os.makedirs(os.path.dirname(yol), exist_ok=True)\n        with open(yol + ".tmp", "w", encoding="utf-8") as f:\n            json.dump(d, f, ensure_ascii=False, indent=1)\n        os.replace(yol + ".tmp", yol)\n        return d\n\n\ndef liste():\n    if not os.path.isdir(KITAPLAR):\n        return []\n    out = []\n    for kid in sorted(os.listdir(KITAPLAR)):\n        if not KIMLIK.match(kid) or not os.path.isdir(os.path.join(KITAPLAR, kid)):\n            continue\n        d = durum_oku(kid)\n        out.append({"kimlik": kid, **{k: d.get(k) for k in ("baslik", "baslik_asil", "yazar", "asama", "hata", "uyari", "guncellendi",\n                                                            "cikti", "cikti_uyari", "studyo", "studyo_uyari",\n                                                            "eklendi", "epublar", "denetim")}})\n    return sorted(out, key=lambda x: -(x.get("eklendi") or 0))\n\n\ndef kitap_yolu(kid):\n    return os.path.join(klasor(kid), "kitap.json")\n\n\ndef surumler(kit):\n    """Kitaptaki dillere g\xc3\xb6re \xc3\xbcretilecek EPUB s\xc3\xbcr\xc3\xbcmleri (dosya eki, diller)."""\n    d = K.diller(kit)\n    asil = kit["kunye"].get("asil_dil", "ar")\n    out = []\n    if "tr" in d:\n        out.append(("turkce", ["tr"]))\n    if "osm" in d:\n        out.append(("osmanlica", ["osm"]))\n    if "tr" in d and "osm" in d:\n        out.append(("turkce-osmanlica", ["tr", "osm"]))\n    if asil not in ("tr", "osm"):  # yabanc\xc4\xb1 as\xc4\xb1l (Arap\xc3\xa7a, \xc4\xb0ngilizce\xe2\x80\xa6): as\xc4\xb1ll\xc4\xb1 s\xc3\xbcr\xc3\xbcmler\n        ad = DIL_AD.get(asil, asil)\n        if asil in d and "tr" in d:\n            out.append((f"{ad}-turkce", [asil, "tr"]))\n        if asil in d:\n            out.append((ad, [asil]))\n    return out\n\n\ndef _dosya_adi(kid, kit):\n    """Sade harfli dosya ad\xc4\xb1 (\xc5\x9fapka/T\xc3\xbcrk\xc3\xa7e harf yok): her cihazda ve a\xc4\x9f payla\xc5\x9f\xc4\xb1m\xc4\xb1nda sorunsuz."""\n    b = kit["kunye"]["baslik"].get("tr") or (kid.split(".")[1] if "." in kid else kid)\n    b = b.translate(str.maketrans("\xc4\xb0\xc4\xb1\xc5\x9e\xc5\x9f\xc4\x9e\xc4\x9f\xc3\x87\xc3\xa7\xc3\x96\xc3\xb6\xc3\x9c\xc3\xbc", "IiSsGgCcOoUu"))\n    b = "".join(c for c in unicodedata.normalize("NFKD", b) if not unicodedata.combining(c))\n    b = re.sub(r"[^A-Za-z0-9\\s-]", "", b).strip()\n    return re.sub(r"\\s+", "_", b)[:60] or "kitap"\n\n\ndef epub_uret(kid):\n    """kitap.json\'dan b\xc3\xbct\xc3\xbcn s\xc3\xbcr\xc3\xbcmleri \xc3\xbcretir ve denetler. Eski EPUB\'lar silinir, yenileri yaz\xc4\xb1l\xc4\xb1r."""\n    kit = K.yukle(kitap_yolu(kid))\n    sorunlar = K.denetle(kit)\n    if sorunlar:\n        raise ValueError("kitap.json yap\xc4\xb1sal hata: " + "; ".join(sorunlar[:5]))\n    ek = os.path.join(klasor(kid), "epub")\n    gecici = ek + ".yeni"\n    shutil.rmtree(gecici, ignore_errors=True)\n    os.makedirs(gecici)\n    ad = _dosya_adi(kid, kit)\n    sonuc = []\n    for ekad, diller in surumler(kit):\n        dosya = f"{ad}_{ekad}.epub"\n        durum_yaz(kid, asama=f"EPUB \xc3\xbcretiliyor: {ekad}")\n        kapak = None  # kitab\xc4\xb1n kendi kapak g\xc3\xb6rseli (PDF\'in ilk sayfas\xc4\xb1 / EPUB\'un kapa\xc4\x9f\xc4\xb1) varsa o\n        if kit["kunye"].get("kapak") and os.path.exists(os.path.join(klasor(kid), kit["kunye"]["kapak"])):\n            kapak = open(os.path.join(klasor(kid), kit["kunye"]["kapak"]), "rb").read()\n        EPUB.uret(kit, diller, os.path.join(gecici, dosya), kapak_png=kapak)\n        durum_yaz(kid, asama=f"Denetleniyor: {ekad}")\n        dn = epubcheck.denetle(os.path.join(gecici, dosya))\n        sonuc.append({"dosya": dosya, "diller": diller, "boyut": os.path.getsize(os.path.join(gecici, dosya)),\n                      "denetim": dn})\n    shutil.rmtree(ek, ignore_errors=True)  # hepsi ba\xc5\x9far\xc4\xb1yla \xc3\xbcretildikten sonra eskiler kalkar\n    os.replace(gecici, ek)\n    try:  # dil klas\xc3\xb6rlerine (T\xc3\xbcrk\xc3\xa7e/, Osmanl\xc4\xb1ca/, T\xc3\xbcrk\xc3\xa7e-Osmanl\xc4\xb1ca/ ...)\n        yazilan = cikti.ciktiya_yaz(kit, sonuc, ek, durum_oku(kid).get("cikti"))\n        durum_yaz(kid, cikti=yazilan, cikti_uyari=None if yazilan is not None else "\xc3\x87\xc4\xb1kt\xc4\xb1 klas\xc3\xb6r\xc3\xbc ba\xc4\x9fl\xc4\xb1 de\xc4\x9fil")\n    except Exception as e:\n        durum_yaz(kid, cikti_uyari=f"\xc3\x87\xc4\xb1kt\xc4\xb1 klas\xc3\xb6r\xc3\xbcne yaz\xc4\xb1lamad\xc4\xb1: {type(e).__name__}: {str(e)[:120]}")\n    ku = kit["kunye"]\n    durum_yaz(kid, epublar=sonuc, asama="haz\xc4\xb1r", hata=None,\n              baslik=ku["baslik"].get("tr") or ku["baslik"].get(ku.get("asil_dil", "ar")),\n              baslik_asil=ku["baslik"].get(ku.get("asil_dil", "ar")),\n              yazar=ku["yazar"].get("tr") or ku["yazar"].get(ku.get("asil_dil", "ar")) or ku["yazar"].get("lat"))\n    return sonuc\n\n\ndef _openiti_ekle(kid, version_uri):\n    satir = katalog.bul(VERI, version_uri)\n    if not satir:\n        raise ValueError("katalogda bulunamad\xc4\xb1: " + version_uri)\n    yol = os.path.join(klasor(kid), "kaynak.txt")\n    if not os.path.exists(yol):\n        durum_yaz(kid, asama="Metin indiriliyor")\n        r = requests.get(satir["url"], timeout=300)\n        r.raise_for_status()\n        r.encoding = "utf-8"\n        with open(yol + ".tmp", "w", encoding="utf-8") as f:\n            f.write(r.text)\n        os.replace(yol + ".tmp", yol)\n    durum_yaz(kid, asama="B\xc3\xb6l\xc3\xbcmler ve sayfalar ayr\xc4\xb1l\xc4\xb1yor")\n    kit = openiti.cevir(open(yol, encoding="utf-8").read(), satir)\n    eski = kitap_yolu(kid)\n    if os.path.exists(eski):  # yeniden ekleme: elle yap\xc4\xb1lan d\xc3\xbczeltmeler ve T\xc3\xbcrk\xc3\xa7e k\xc3\xbcnye korunur\n        onceki = K.yukle(eski)\n        kit["kunye"]["baslik"].update({k: v for k, v in onceki["kunye"]["baslik"].items() if k != "ar"})\n        kit["kunye"]["yazar"].update({k: v for k, v in onceki["kunye"]["yazar"].items() if k not in ("ar", "lat")})\n    K.kaydet(kit, eski)\n\n\ndef _dosya_ekle(kid, yol):\n    """Elindeki kitap (PDF/EPUB/DOCX/TXT) -> kitap.json (T\xc3\xbcrk\xc3\xa7e) -> Osmanl\xc4\xb1ca -> EPUB\'lar."""\n    if not os.path.exists(yol):\n        raise FileNotFoundError("Kaynak dosya bulunamad\xc4\xb1: " + yol)\n    kit = kaynak.cevir(yol, lambda m: durum_asama(kid, m), {"yol": yol}, kapak_yolu=os.path.join(klasor(kid), "kapak"))\n    try:  # 0.5.23: kitap raporu (rapor.json, rapor.txt); hata kitab\xc4\xb1 durdurmaz\n        from . import rapor\n        rapor.kaydet(klasor(kid), rapor.al())\n    except Exception:\n        pass\n    eski = kitap_yolu(kid)\n    if os.path.exists(eski):  # yeniden i\xc5\x9fleme: \xc3\xb6nceki h\xc3\xa2l yedeklenir, T\xc3\xbcrk\xc3\xa7e k\xc3\xbcnye d\xc3\xbczeltmeleri korunur\n        onceki = K.yukle(eski)\n        shutil.copy2(eski, eski + ".yedek")\n        for alan in ("baslik", "yazar"):\n            if onceki["kunye"].get(alan, {}).get("elle"):\n                kit["kunye"][alan] = onceki["kunye"][alan]\n    K.kaydet(kit, eski)  # Osmanl\xc4\xb1ca sonra, ayr\xc4\xb1 i\xc5\x9f (\xc3\xb6nce kitab\xc4\xb1n kendi dilindeki EPUB\'u haz\xc4\xb1r olur)\n    try:   # 0.5.53: yeni metin: yapay zek\xc3\xa2 denetimi bunun \xc3\xbczerinden yeniden yap\xc4\xb1l\xc4\xb1r (sakl\xc4\xb1 cevaplarla)\n        os.remove(os.path.join(klasor(kid), "kitap.denetimsiz.json"))\n    except OSError:\n        pass\n\n\ndef _osmanlica(kid, zorla=False):\n    kit = K.yukle(kitap_yolu(kid))\n    durum_asama(kid, "Osmanl\xc4\xb1caya \xc3\xa7evriliyor")\n    try:\n        osmanlica.kitabi_cevir(kit, lambda m: durum_asama(kid, m), zorla=zorla)\n        K.kaydet(kit, kitap_yolu(kid))\n        durum_yaz(kid, uyari=None)\n    except Exception as e:  # \xc3\xa7evirici kapal\xc4\xb1ysa T\xc3\xbcrk\xc3\xa7e EPUB yine \xc3\xbcretilir\n        durum_yaz(kid, uyari=f"Osmanl\xc4\xb1ca \xc3\xa7evrilemedi ({type(e).__name__}: {str(e)[:120]}); sadece T\xc3\xbcrk\xc3\xa7e \xc3\xbcretildi")\n\n\ndef _studyoya_zincirle(kid, guncelle=False, yalniz_var_olan=False, elle=False):\n    """Tur 2/A: Osmanl\xc4\xb1ca ve EPUB\'lar bitince T\xc3\xbcrk\xc3\xa7e kitap kendili\xc4\x9finden St\xc3\xbcdyo\'ya gider (seslendirme ve \xc3\xb6teki bi\xc3\xa7imler).\n    Kitab\xc4\xb1n St\xc3\xbcdyo i\xc5\x9fi zaten varsa yeni i\xc5\x9f a\xc3\xa7\xc4\xb1lmaz (d\xc3\xbczeltmeden sonra yenileme tur 2/C). Osmanl\xc4\xb1ca \xc3\xa7evrilemediyse\n    g\xc3\xb6nderilmez: St\xc3\xbcdyo Osmanl\xc4\xb1cay\xc4\xb1 ikinci kez \xc3\xa7evirmesin; \'Osmanl\xc4\xb1cay\xc4\xb1 yeniden \xc3\xa7evir\' ba\xc5\x9far\xc4\xb1l\xc4\xb1 olunca gider."""\n    kit = K.yukle(kitap_yolu(kid))\n    if kit["kunye"].get("asil_dil") != "tr" or "tr" not in K.diller(kit):\n        return\n    if not elle and not yz.ayarlar().get("seslendirme_otomatik", False):\n        # 0.5.53 (Zahir, 28 Ekim): bilinen hatalar d\xc3\xbczelene kadar seslendirme kendili\xc4\x9finden ba\xc5\x9flamaz; Ayarlar\'dan a\xc3\xa7\xc4\xb1l\xc4\xb1r\n        durum_yaz(kid, studyo_uyari="Seslendirme bekletiliyor (Yapay zek\xc3\xa2 ayarlar\xc4\xb1nda \'seslendirme kendili\xc4\x9finden\' kapal\xc4\xb1).")\n        return\n    d = durum_oku(kid)\n    if d.get("uyari"):\n        durum_yaz(kid, studyo_uyari="Osmanl\xc4\xb1ca \xc3\xa7evrilemedi\xc4\x9fi i\xc3\xa7in seslendirmeye g\xc3\xb6nderilmedi; "\n                                    "\'Osmanl\xc4\xb1cay\xc4\xb1 yeniden \xc3\xa7evir\' ba\xc5\x9far\xc4\xb1l\xc4\xb1 olunca kendili\xc4\x9finden gider.")\n        return\n    eski = (d.get("studyo") or {}).get("is")\n    if eski and cikti.studyo_isi_var(eski):\n        if guncelle:   # tur 2/C: var olan i\xc5\x9f yeni metinle yenilenir (yaln\xc4\xb1z de\xc4\x9fi\xc5\x9fen b\xc3\xb6l\xc3\xbcmlerin sesi yeniden \xc3\xbcretilir)\n            try:\n                durum_yaz(kid, studyo=cikti.studyoyu_guncelle(kit, eski), studyo_uyari=None)\n            except Exception as e:\n                traceback.print_exc()\n                durum_yaz(kid, studyo_uyari=f"Seslendirme yenilenemedi: {type(e).__name__}: {str(e)[:150]}")\n        return\n    if yalniz_var_olan:\n        return\n    try:\n        durum_yaz(kid, studyo=cikti.studyoya_gonder(kit), studyo_uyari=None)\n    except Exception as e:\n        traceback.print_exc()\n        durum_yaz(kid, studyo_uyari=f"Seslendirmeye g\xc3\xb6nderilemedi: {type(e).__name__}: {str(e)[:150]}")\n\n\n# ======================= 0.5.53: yapay zek\xc3\xa2 denetimi =======================\n_kuyruk_den = queue.Queue()\nDENETIM_SERIT = int(os.environ.get("STUDYO_DENETIM_SERIT", "3"))\n\n\ndef denetim_iscisi():\n    while True:\n        tur, kid, arg, nesil = _kuyruk_den.get()\n        try:\n            with _kilit:\n                gecerli = nesil == _nesil.get(kid, 0)\n            if gecerli and os.path.exists(kitap_yolu(kid)):\n                sonra = _denetim(kid, arg)\n                if sonra and kid not in _silinecek:\n                    is_ekle(*sonra)\n        except IsIptal:\n            pass\n        except Exception as e:\n            traceback.print_exc()\n            # 0.5.59: beklenmeyen hata kitab\xc4\xb1 eski a\xc5\x9fama yaz\xc4\xb1s\xc4\xb1yla b\xc4\xb1rakmas\xc4\xb1n: hata g\xc3\xb6r\xc3\xbcn\xc3\xbcr, "Yapay zek\xc3\xa2 ile denetle" ile yeniden\n            try:\n                durum_yaz(kid, asama="hata", hata=f"Denetim: {type(e).__name__}: {str(e)[:200]}",\n                          denetim={"durum": "hata", "hata": f"{type(e).__name__}: {str(e)[:200]}", "tarih": int(time.time())})\n            except Exception:\n                traceback.print_exc()\n        finally:\n            _kuyruk_den.task_done()\n\n\ndef _kitap_ozu(yol):\n    import hashlib\n    try:\n        with open(yol, "rb") as f:\n            return hashlib.sha1(f.read()).hexdigest()\n    except OSError:\n        return None\n\n\nDENETIM_GECICI_BEKLE = int(os.environ.get("STUDYO_DENETIM_BEKLE", "1800"))   # 0.5.57: Gemini cevap vermezse bekleme (sn)\nDENETIM_GECICI_DENEME = 8\n\n\ndef _denetim(kid, arg=None):\n    """Kitab\xc4\xb1n T\xc3\xbcrk\xc3\xa7esini yapay zek\xc3\xa2yla denetler (kutuphane/denetim.py). Okunmaz par\xc3\xa7alar blokta ses_yok olur (metin de\xc4\x9fi\xc5\x9fmez),\n    kelime d\xc3\xbczeltmeleri metne uygulan\xc4\xb1r. Her zaman denetimsiz h\xc3\xa2lin (kitap.denetimsiz.json) \xc3\xbczerinden: yeniden denetimde i\xc5\x9faretler\n    yinelenmez, sakl\xc4\xb1 cevaplarla h\xc4\xb1zl\xc4\xb1d\xc4\xb1r. Bitince Osmanl\xc4\xb1ca (d\xc3\xbczeltilmi\xc5\x9f kelimelerle) ve \xc3\xa7\xc4\xb1kt\xc4\xb1lar. D\xc3\xb6nen: sonraki i\xc5\x9f."""\n    from . import denetim as D\n    yol, ham = kitap_yolu(kid), os.path.join(klasor(kid), "kitap.denetimsiz.json")\n    with kitap_kilidi(kid):\n        if not os.path.exists(ham):\n            shutil.copy2(yol, ham)\n        oz = _kitap_ozu(yol)\n        kit = K.yukle(ham)\n    if kit["kunye"].get("asil_dil") != "tr":\n        return None\n    ilerleme = lambda m: durum_asama(kid, m)\n    durum_asama(kid, "Yapay zek\xc3\xa2 denetimi ba\xc5\x9fl\xc4\xb1yor")\n    # kitapta zaten bulunan okunmaz i\xc5\x9faretleri (Haz\xc4\xb1rl\xc4\xb1k\'\xc4\xb1n EPUB\'u) metne geri konur: g\xc3\xb6revler onlar\xc4\xb1 yeniden sormaz\n    for b in kit["bloklar"]:\n        sy = (b.get("ses_yok") or {}).get("tr")\n        if sy and b["metin"].get("tr"):\n            b["metin"]["tr"] = K.ses_yok_isaretle(b["metin"]["tr"], sy)\n    dn = D.Denetci(klasor(kid), ilerleme=ilerleme)\n    try:\n        dn.calistir(kit)\n    except yz.GunlukSinir:\n        ne = yz.sifirlanma()\n        saat = time.strftime("%H:%M", time.localtime(ne))\n        durum_yaz(kid, asama=f"Yapay zek\xc3\xa2: Google\'\xc4\xb1n g\xc3\xbcnl\xc3\xbck \xc3\xbccretsiz s\xc4\xb1n\xc4\xb1r\xc4\xb1 doldu; {saat}\'de kald\xc4\xb1\xc4\x9f\xc4\xb1 yerden s\xc3\xbcrecek",\n                  denetim={"durum": "bekliyor", "devam": int(ne)})\n        threading.Timer(max(60, ne - time.time()), lambda: is_ekle("denetim", kid, arg)).start()\n        return None\n    except yz.GeciciHata as e:   # 0.5.57: Gemini \xc5\x9fu an cevap vermiyor: kitap denetimsiz s\xc3\xbcrmez, 30 dk sonra yeniden (en \xc3\xa7ok 8 kez)\n        sayi = int(((durum_oku(kid).get("denetim") or {}).get("gecici") or 0)) + 1\n        if sayi <= DENETIM_GECICI_DENEME:\n            ne = time.time() + DENETIM_GECICI_BEKLE\n            saat = time.strftime("%H:%M", time.localtime(ne))\n            durum_yaz(kid, asama=f"Yapay zek\xc3\xa2: Gemini \xc5\x9fu an cevap vermiyor; {saat}\'de yeniden denenecek ({sayi}/{DENETIM_GECICI_DENEME})",\n                      denetim={"durum": "bekliyor", "devam": int(ne), "gecici": sayi})\n            threading.Timer(DENETIM_GECICI_BEKLE, lambda: is_ekle("denetim", kid, arg)).start()\n            return None\n        traceback.print_exc()\n        durum_yaz(kid, denetim={"durum": "hata", "hata": f"{type(e).__name__}: {str(e)[:200]}", "tarih": int(time.time())})\n        return ("osmanlica", kid)\n    except IsIptal:\n        raise\n    except Exception as e:   # denetim yap\xc4\xb1lamad\xc4\xb1: kitap beklemez (Osmanl\xc4\xb1ca ve \xc3\xa7\xc4\xb1kt\xc4\xb1lar denetimsiz s\xc3\xbcrer)\n        traceback.print_exc()\n        durum_yaz(kid, denetim={"durum": "hata", "hata": f"{type(e).__name__}: {str(e)[:200]}", "tarih": int(time.time())})\n        return ("osmanlica", kid)\n    for b in kit["bloklar"]:      # i\xc5\x9faretler -> ses_yok (metin i\xc5\x9faretsiz)\n        t = b["metin"].get("tr")\n        if t and (K.SES_AC in t or K.SES_KAPA in t):\n            t, sy = K.ses_yok_ayir(t)\n            b["metin"]["tr"] = t\n            if sy:\n                b.setdefault("ses_yok", {})["tr"] = sy\n            else:\n                (b.get("ses_yok") or {}).pop("tr", None)\n    for n in (kit.get("dipnotlar") or {}).values():\n        if isinstance(n.get("metin"), dict) and n["metin"].get("tr"):\n            n["metin"]["tr"] = K.ses_yok_ayir(n["metin"]["tr"])[0]\n    m = dn.model\n    ozet = dn.ozet()\n    okunmaz = sum(len((b.get("ses_yok") or {}).get("tr", [])) for b in kit["bloklar"])\n    rapor = dn.rapor_metni(kit["kunye"]["baslik"].get("tr") or kid, [f"okunmaz i\xc5\x9faretli par\xc3\xa7a: {okunmaz}"])\n    with kitap_kilidi(kid):\n        if _kitap_ozu(yol) != oz:   # bu s\xc4\xb1rada kitap de\xc4\x9fi\xc5\x9fti (d\xc3\xbczeltme ya da yeniden i\xc5\x9fleme): denetim yeniden (sakl\xc4\xb1 cevaplarla)\n            return ("denetim", kid, arg)\n        K.kaydet(kit, yol)\n    with open(os.path.join(klasor(kid), "denetim.txt"), "w", encoding="utf-8") as f:\n        f.write(rapor)\n    durum_yaz(kid, denetim={"durum": "hazir", "tarih": int(time.time()), "ozet": ozet, "okunmaz": okunmaz,\n                            "cagri": getattr(m, "sayac", {}).get("cagri", 0), "model": dict(getattr(m, "kullanilan", {}) or {})})\n    return ("osmanlica", kid)\n\n\ndef durum_asama(kid, mesaj):\n    if kid in _silinecek:  # 0.5.19: kitap silinmek istendi: i\xc5\x9f burada durur (OCR\'da en ge\xc3\xa7 4 sayfada bir)\n        raise IsIptal("Kitap silinmek \xc3\xbczere: i\xc5\x9f durduruldu")\n    durum_yaz(kid, asama=mesaj)\n\n\ndef _is_kilidi(kid):\n    with _kilit:\n        return _is_kilitleri.setdefault(kid, threading.Lock())\n\n\n_kuyruk_osm = type(_kuyruk)()  # 0.5.25: Osmanl\xc4\xb1ca ayr\xc4\xb1 \xc5\x9ferit (inceleme s\xc4\xb1ras\xc4\xb1n\xc4\xb1 beklemez)\n\n\ndef isci(agir=False):\n    """0.5.17: iki \xc5\x9ferit. Hafif \xc5\x9ferit, OCR gerektiren dosya i\xc5\x9fini a\xc4\x9f\xc4\xb1r \xc5\x9feride devreder. Ayn\xc4\xb1 kitab\xc4\xb1n iki i\xc5\x9fi ayn\xc4\xb1 anda\n    \xc3\xa7al\xc4\xb1\xc5\x9fmaz: kitab\xc4\xb1n i\xc5\x9fi a\xc4\x9f\xc4\xb1r \xc5\x9feritte s\xc3\xbcrerken gelen hafif i\xc5\x9f a\xc4\x9f\xc4\xb1r \xc5\x9feridin arkas\xc4\xb1na ge\xc3\xa7er."""\n    kuyruk = _kuyruk_osm if agir == "osm" else (_kuyruk_agir if agir else _kuyruk)\n    serit = "osm" if agir == "osm" else ("agir" if agir else "hafif")\n    if agir == "osm":\n        agir = False  # hafif \xc5\x9ferit gibi: kitab\xc4\xb1n ba\xc5\x9fka i\xc5\x9fi s\xc3\xbcr\xc3\xbcyorsa a\xc4\x9f\xc4\xb1r \xc5\x9feridin arkas\xc4\xb1na ge\xc3\xa7er\n    while True:\n        tur, kid, arg, nesil = kuyruk.get()\n        with _kilit:  # 0.5.19: silinen kitab\xc4\xb1n kuyrukta kalan i\xc5\x9fi atlan\xc4\xb1r\n            gecerli = nesil == _nesil.get(kid, 0)\n            if gecerli:\n                _calisan[serit] = kid\n        if not gecerli:\n            kuyruk.task_done()\n            continue\n        try:\n            if not agir and tur == "dosya":\n                durum_asama(kid, "Dosya inceleniyor")\n                if kaynak.ocr_gerekir(arg):\n                    durum_yaz(kid, asama="OCR s\xc4\xb1ras\xc4\xb1nda")\n                    _kuyruk_agir.put((tur, kid, arg, nesil))\n                    continue\n            kilit = _is_kilidi(kid)\n            if not agir and not kilit.acquire(blocking=False):\n                # bu kitab\xc4\xb1n i\xc5\x9fi a\xc4\x9f\xc4\xb1r \xc5\x9feritte s\xc3\xbcr\xc3\xbcyor (hafif \xc5\x9ferit tek i\xc5\x9f par\xc3\xa7ac\xc4\xb1\xc4\x9f\xc4\xb1): i\xc5\x9f a\xc4\x9f\xc4\xb1r \xc5\x9feridin arkas\xc4\xb1na ge\xc3\xa7er,\n                # hafif \xc5\x9ferit beklemez ve d\xc3\xb6n\xc3\xbcp durmaz\n                _kuyruk_agir.put((tur, kid, arg, nesil))\n                continue\n            if agir:\n                kilit.acquire()  # hafif \xc5\x9feritteki k\xc4\xb1sa i\xc5\x9f bitene kadar bekler\n            try:\n                sonra = _isle(tur, kid, arg)\n            finally:\n                kilit.release()\n            if sonra:  # 0.5.47: Osmanlica bitti; ciktilar (EPUB/PDF/DOCX, Studyo) hafif seritte, Osmanlica seridi sonraki kitaba gecer\n                is_ekle(*sonra)\n        except IsIptal:\n            pass\n        except Exception:\n            traceback.print_exc()\n        finally:\n            with _kilit:\n                _calisan.pop(serit, None)\n                sonra_sil = kid in _silinecek and kid not in _calisan.values()\n                if sonra_sil:\n                    _silinecek.discard(kid)\n            if sonra_sil:\n                sil(kid)\n            kuyruk.task_done()\n\n\ndef _isle(tur, kid, arg):\n    if True:\n        with _kilit:\n            _bekleyen_epub.discard(kid)\n        try:\n            if tur in ("openiti", "dosya", "osmanlica", "kunye"):\n                with kitap_kilidi(kid):  # bu s\xc4\xb1rada okuma ekran\xc4\xb1ndan d\xc3\xbczeltme yap\xc4\xb1lamaz\n                    if tur == "openiti":\n                        _openiti_ekle(kid, arg)\n                    elif tur == "dosya":\n                        _dosya_ekle(kid, arg)\n                    elif tur == "osmanlica":\n                        _osmanlica(kid, zorla=bool(arg))\n                    elif tur == "kunye":\n                        kit = K.yukle(kitap_yolu(kid))\n                        try:\n                            osmanlica.kunye_cevir(kit)\n                            K.kaydet(kit, kitap_yolu(kid))\n                        except Exception as e:\n                            durum_yaz(kid, uyari=f"K\xc3\xbcnyenin Osmanl\xc4\xb1cas\xc4\xb1 \xc3\xa7evrilemedi: {type(e).__name__}")\n            if kid in _silinecek:  # 0.5.19: kitap silinecek: EPUB, St\xc3\xbcdyo ve Osmanl\xc4\xb1ca zinciri yok\n                return\n            if tur == "osmanlica":\n                return ("osm_cikti", kid)  # 0.5.47: Osmanlica seridi cikti uretimini beklemez\n            epub_uret(kid)\n            if tur in ("osmanlica", "osm_cikti"):  # tur 2/A: Osmanl\xc4\xb1ca ve EPUB\'lar haz\xc4\xb1r -> kendili\xc4\x9finden St\xc3\xbcdyo\n                _studyoya_zincirle(kid, guncelle=True)\n            elif tur in ("epub", "kunye"):  # tur 2/C: okuma ekran\xc4\xb1nda d\xc3\xbczeltme -> St\xc3\xbcdyo i\xc5\x9fi (ses ve bi\xc3\xa7imler) yenilenir\n                _studyoya_zincirle(kid, guncelle=True, yalniz_var_olan=True)\n            # 1. a\xc5\x9fama bitti: kitap kendi dilinde K\xc3\xbct\xc3\xbcphane\'de. 2. a\xc5\x9fama: T\xc3\xbcrk\xc3\xa7eyse Osmanl\xc4\xb1ca (\xc3\xa7eviri yok; OpenITI yaln\xc4\xb1z Arap\xc3\xa7a EPUB)\n            if tur == "dosya":\n                kit = K.yukle(kitap_yolu(kid))\n                if kit["kunye"].get("asil_dil") == "tr":\n                    # 0.5.53: yapay zek\xc3\xa2 a\xc3\xa7\xc4\xb1ksa \xc3\xb6nce denetim (d\xc3\xbczeltilmi\xc5\x9f kelimeler Osmanl\xc4\xb1caya da ge\xc3\xa7sin), sonra Osmanl\xc4\xb1ca\n                    is_ekle("denetim" if yz.acik() else "osmanlica", kid, tur="epub")\n        except IsIptal:\n            return\n        except Exception as e:\n            if kid in _silinecek:\n                return\n            traceback.print_exc()\n            durum_yaz(kid, asama="hata", hata=f"{type(e).__name__}: {e}")\n\n\ndef is_ekle(is_turu, kid, arg=None, **durum):\n    with _kilit:\n        if is_turu == "epub" and kid in _bekleyen_epub:\n            return  # zaten kuyrukta: tek sefer \xc3\xbcretilir\n        if is_turu == "epub":\n            _bekleyen_epub.add(kid)\n    # 0.5.17: yaz\xc4\xb1 i\xc5\x9fi s\xc3\xb6yler (T\xc3\xbcrk\xc3\xa7e EPUB haz\xc4\xb1rken "s\xc4\xb1rada" yan\xc4\xb1lt\xc4\xb1c\xc4\xb1yd\xc4\xb1); i\xc5\x9fin t\xc3\xbcr\xc3\xbc yeniden ba\xc5\x9flatma i\xc3\xa7in saklan\xc4\xb1r\n    yazi = {"osmanlica": "Osmanl\xc4\xb1ca s\xc4\xb1rada", "epub": "EPUB s\xc4\xb1rada", "kunye": "EPUB s\xc4\xb1rada",\n            "osm_cikti": "\xc3\x87\xc4\xb1kt\xc4\xb1lar s\xc4\xb1rada", "denetim": "Yapay zek\xc3\xa2 denetimi s\xc4\xb1rada"}.get(is_turu, "s\xc4\xb1rada")\n    durum_yaz(kid, asama=yazi, hata=None, is_turu=is_turu, is_arg=arg, **durum)\n    kuyruk = _kuyruk_osm if is_turu == "osmanlica" else _kuyruk_den if is_turu == "denetim" else _kuyruk\n    kuyruk.put((is_turu, kid, arg, _nesil.get(kid, 0)))\n\n\ndef baslat():\n    threading.Thread(target=isci, daemon=True, name="kutuphane-hafif").start()\n    threading.Thread(target=isci, args=(True,), daemon=True, name="kutuphane-agir").start()\n    threading.Thread(target=isci, args=("osm",), daemon=True, name="kutuphane-osmanlica").start()\n    for n in range(DENETIM_SERIT):   # 0.5.53: yapay zek\xc3\xa2 denetimi ayn\xc4\xb1 anda 3 kitap (dakika s\xc4\xb1n\xc4\xb1r\xc4\xb1 yz\'de ortak say\xc4\xb1l\xc4\xb1r)\n        threading.Thread(target=denetim_iscisi, daemon=True, name=f"kutuphane-denetim-{n}").start()\n    # 0.5.8: \xc3\xa7eviri kald\xc4\xb1r\xc4\xb1ld\xc4\xb1; \xc3\xa7eviri izleyicisi ba\xc5\x9flat\xc4\xb1lmaz\n    # yeniden ba\xc5\x9flatmada yar\xc4\xb1m kalan i\xc5\x9fler kuyru\xc4\x9fa geri al\xc4\xb1n\xc4\xb1r\n    for k in liste():\n        if durum_oku(k["kimlik"]).get("silinecek"):  # 0.5.19: silinmek istenirken yeniden ba\xc5\x9flat\xc4\xb1ld\xc4\xb1\n            sil(k["kimlik"])\n            continue\n        if k.get("asama") not in (None, "haz\xc4\xb1r", "hata"):\n            d = durum_oku(k["kimlik"])\n            if d.get("is_turu"):  # 0.5.17: yar\xc4\xb1m kalan i\xc5\x9fin kendisi (Osmanl\xc4\xb1ca i\xc5\x9fi "epub" diye geri al\xc4\xb1n\xc4\xb1yordu)\n                is_ekle(d["is_turu"], k["kimlik"], d.get("is_arg"))\n            else:\n                is_ekle(d.get("tur", "epub"), k["kimlik"], d.get("kaynak_kimlik"))\n        _bekleyen_denetim(k)\n\n\ndef _bekleyen_denetim(k):\n    """0.5.60: g\xc3\xbcnl\xc3\xbck s\xc4\xb1n\xc4\xb1r y\xc3\xbcz\xc3\xbcnden bekleyen denetim yeniden ba\xc5\x9flatmada kaybolmas\xc4\xb1n (Timer bellekteydi). 2 Kas\xc4\xb1m: Tahrif 1-3\n    "bekliyor" kald\xc4\xb1; a\xc5\x9famalar\xc4\xb1 s\xc4\xb1radaki eski i\xc5\x9flerle "haz\xc4\xb1r" oldu\xc4\x9fu i\xc3\xa7in yukar\xc4\xb1daki geri alma onlar\xc4\xb1 g\xc3\xb6rmedi."""\n    d = durum_oku(k["kimlik"])\n    den = d.get("denetim") or {}\n    if den.get("durum") != "bekliyor":\n        return\n    if k.get("asama") not in (None, "haz\xc4\xb1r", "hata") and d.get("is_turu") == "denetim":\n        return      # denetim i\xc5\x9fi zaten geri al\xc4\xb1nd\xc4\xb1\n    kid, arg = k["kimlik"], d.get("is_arg") if d.get("is_turu") == "denetim" else None\n    gecikme = max(5, int(den.get("devam") or 0) - time.time())\n    threading.Timer(gecikme, lambda: is_ekle("denetim", kid, arg)).start()\n\n\ndef sil(kid):\n    shutil.rmtree(klasor(kid), ignore_errors=True)\n\n\ndef sil_iste(kid):\n    """0.5.19: kitab\xc4\xb1 sil. S\xc4\xb1rada bekliyorsa (ya da haz\xc4\xb1r/hata) hemen silinir: kuyruktaki i\xc5\x9fleri atlan\xc4\xb1r.\n    \xc4\xb0\xc5\x9fi \xc5\x9fu an \xc3\xa7al\xc4\xb1\xc5\x9f\xc4\xb1yorsa i\xc5\x9f durdurulur ve kitap ard\xc4\xb1ndan silinir. D\xc3\xb6nen: \\"silindi\\" ya da \\"durduruluyor\\"."""\n    with _kilit:\n        _nesil[kid] = _nesil.get(kid, 0) + 1\n        _bekleyen_epub.discard(kid)\n        calisiyor = kid in _calisan.values()\n        if calisiyor:\n            _silinecek.add(kid)\n    if calisiyor:\n        durum_yaz(kid, silinecek=True)\n        return "durduruluyor"\n    sil(kid)\n    return "silindi"\n', 'app/worker.py': b'"""St\xc3\xbcdyo i\xc5\x9f ak\xc4\xb1\xc5\x9f\xc4\xb1.\n\nHer kitap \xc5\x9fu a\xc5\x9famalardan ge\xc3\xa7er:\n  detect    \xe2\x86\x92 dil belirlenir\n  (T\xc3\xbcrk\xc3\xa7e olmayan kitap durur: St\xc3\xbcdyo yaln\xc4\xb1z T\xc3\xbcrk\xc3\xa7e kitap al\xc4\xb1r; Translate 5 Ekim 2026\'da kald\xc4\xb1r\xc4\xb1ld\xc4\xb1)\n  produce   \xe2\x86\x92 Kitap Okuma seslendirir  +  Osmanl\xc4\xb1ca \xc3\xa7evirici par\xc3\xa7alar\xc4\xb1 \xc3\xa7evirir (ayn\xc4\xb1 anda)\n  done\n"""\nimport glob\nimport json\nimport os\nimport re\nimport shutil\nimport threading\nimport time\nimport traceback\n\nimport requests\n\nfrom . import clients, db, textsrc, duzelt\nfrom .ses import ses_metni\nfrom .detect import detect_lang, sample_text\n\nTEXT_DIR = os.environ.get("OKUMA_TEXT_DIR", "/okuma-text")\n# Kitap Okuma\'n\xc4\xb1n \xc3\xa7al\xc4\xb1\xc5\x9fma klas\xc3\xb6r\xc3\xbc dedplay/.seslendirme: St\xc3\xbcdyo onu /dedplay ba\xc4\x9flant\xc4\xb1s\xc4\xb1n\xc4\xb1n i\xc3\xa7inden g\xc3\xb6r\xc3\xbcr, b\xc3\xb6ylece\n# MP3/M4B sabit ba\xc4\x9flant\xc4\xb1yla verilebilir (iki ayr\xc4\xb1 Docker ba\xc4\x9flant\xc4\xb1s\xc4\xb1 aras\xc4\xb1nda sabit ba\xc4\x9flant\xc4\xb1 kurulamaz)\nOUTPUT_DIR = os.environ.get("OUTPUT_DIR") or ("/dedplay/.seslendirme" if os.path.isdir("/dedplay/.seslendirme") else "/cikti")\nTICK = 4\nOSM_BUDGET = 20  # saniye: her turda Osmanl\xc4\xb1caya ayr\xc4\xb1lan en fazla s\xc3\xbcre\n\n\ndef ok_filename(j):\n    """Kitab\xc4\xb1n Kitap Okuma\'ya hangi dosya ad\xc4\xb1yla g\xc3\xb6nderildi\xc4\x9fi."""\n    if not j["book_name"]:\n        return None\n    if j["lang"] == "tr":\n        return j["book_name"] + os.path.splitext(j["filename"])[1].lower()\n    return j["book_name"] + ".epub"\n\n\ndef parts_to_epub(parts, title, out_path):\n    """Temiz metin par\xc3\xa7alar\xc4\xb1ndan EPUB: her par\xc3\xa7a ayr\xc4\xb1 b\xc3\xb6l\xc3\xbcm (Kitap Okuma her b\xc3\xb6l\xc3\xbcm\xc3\xbc bir ses par\xc3\xa7as\xc4\xb1 yapar)."""\n    import html as _html\n    from ebooklib import epub\n    book = epub.EpubBook()\n    book.set_identifier(f"dedplay-{abs(hash(title))}")\n    book.set_title(title)\n    book.set_language("tr")\n    bolumler = []\n    for i, p in enumerate(parts, 1):\n        ch = epub.EpubHtml(title=f"{i}", file_name=f"b{i:04d}.xhtml", lang="tr")\n        satirlar = [re.sub(r"^\\s*\\d{1,3}\\s*[.)]\\s*", "", x) for x in p["tr"].split("\\n")]  # ayet/madde no okunmaz\n        satirlar = [ses_metni(x) for x in satirlar]  # 0.5.43: yazar\xc4\xb1n kaynak g\xc3\xb6sterimleri ("(Kehf, 110)", "(M. 54)", "(M\xc3\xbcslim)") okunmaz\n        satirlar = [x for x in satirlar if x.strip()]\n        if not satirlar:   # 0.5.60: sesi olmayan par\xc3\xa7a (hepsi okunmaz/kaynak): bo\xc5\x9f <body> ebooklib\'de "Document is empty" hatas\xc4\xb1\n            continue\n        # tur 2/C: par\xc3\xa7an\xc4\xb1n ilk sat\xc4\xb1r\xc4\xb1 (b\xc3\xb6l\xc3\xbcm ba\xc5\x9fl\xc4\xb1\xc4\x9f\xc4\xb1) <h1>: Kitap Okuma M4B b\xc3\xb6l\xc3\xbcm ad\xc4\xb1n\xc4\xb1 buradan al\xc4\xb1r (Bolum_001 yerine)\n        bas = f"<h1>{_html.escape(satirlar[0])}</h1>" if satirlar and len(satirlar[0]) <= 120 else ""\n        govde = satirlar[1:] if bas else satirlar\n        ch.content = "<html><body>" + bas + "".join(f"<p>{_html.escape(x)}</p>" for x in govde) + "</body></html>"\n        book.add_item(ch)\n        bolumler.append(ch)\n    book.add_item(epub.EpubNcx())\n    book.add_item(epub.EpubNav())\n    book.spine = bolumler\n    epub.write_epub(out_path, book)\n    return out_path\n\n\ndef txt_to_epub(txt_path, title, out_path):\n    """Kitap Okuma sadece PDF/EPUB kabul etti\xc4\x9fi i\xc3\xa7in d\xc3\xbcz metni basit bir EPUB\'a \xc3\xa7evirir."""\n    import html as _html\n    from ebooklib import epub\n    text = open(txt_path, encoding="utf-8").read()\n    paras = [p.strip() for p in re.split(r"\\n\\s*\\n|\\n", text) if p.strip()]\n    book = epub.EpubBook()\n    book.set_identifier(f"dedplay-metin-{abs(hash(title))}")\n    book.set_title(title)\n    book.set_language("tr")\n    ch = epub.EpubHtml(title=title, file_name="metin.xhtml", lang="tr")\n    ch.content = "<html><body>" + "".join(f"<p>{_html.escape(p)}</p>" for p in paras) + "</body></html>"\n    book.add_item(ch)\n    book.add_item(epub.EpubNcx())\n    book.add_item(epub.EpubNav())\n    book.spine = ["nav", ch]\n    epub.write_epub(out_path, book)\n    return out_path\n\n\ndef _natural(path):\n    m = re.search(r"(\\d+)", os.path.basename(path))\n    return int(m.group(1)) if m else 0\n\n\ndef _read(path):\n    raw = open(path, "rb").read()\n    for enc in ("utf-8-sig", "cp1254", "latin-1"):\n        try:\n            return raw.decode(enc)\n        except UnicodeDecodeError:\n            continue\n    return ""\n\n\nclass Worker(threading.Thread):\n    def __init__(self):\n        super().__init__(daemon=True)\n        self.seen = {}  # job_id -> (dosya say\xc4\xb1s\xc4\xb1, ka\xc3\xa7 turdur sabit)\n        self.no_orig = set()  # ilk metni \xc3\xa7\xc4\xb1kar\xc4\xb1lamayan i\xc5\x9fler (Kitap Okuma\'n\xc4\xb1n metnine d\xc3\xb6n\xc3\xbcl\xc3\xbcr)\n        self.kayip = {}  # job_id -> Kitap Okuma listesinde ka\xc3\xa7 turdur g\xc3\xb6r\xc3\xbcnm\xc3\xbcyor\n\n    def run(self):\n        while True:\n            for job in db.active_jobs():\n                try:\n                    self.step(job)\n                    if job["note"]:\n                        db.update(job["id"], note=None)\n                except requests.RequestException as e:\n                    # Ge\xc3\xa7ici ba\xc4\x9flant\xc4\xb1 sorunu: i\xc5\x9fi durdurma, bir sonraki turda tekrar dene\n                    db.update(job["id"], note=f"Ba\xc4\x9flant\xc4\xb1 sorunu, tekrar denenecek: {str(e)[:150]}")\n                except Exception as e:\n                    traceback.print_exc()\n                    db.update(job["id"], status="error", error=str(e)[:500])\n            time.sleep(TICK)\n\n    # ------------------------------------------------------------\n    def step(self, j):\n        jid, stage = j["id"], j["stage"]\n        src = db.source_path(jid, j["filename"])\n\n        if stage == "detect":\n            lang = j["lang"]\n            if lang == "auto":\n                lang = detect_lang(sample_text(src))\n                if lang is None and src.lower().endswith(".pdf"):\n                    lang = _ocr_ile_dil(src)  # taranm\xc4\xb1\xc5\x9f PDF: birka\xc3\xa7 sayfay\xc4\xb1 OCR\'lay\xc4\xb1p dili oradan anla\n                if lang is None:\n                    raise RuntimeError("Kitab\xc4\xb1n dili alg\xc4\xb1lanamad\xc4\xb1 (taranm\xc4\xb1\xc5\x9f bir kitap olabilir). "\n                                       "Silip \'Kitap dili\' se\xc3\xa7ene\xc4\x9fini elle belirleyerek yeniden ekleyin.")\n            if lang == "tr":\n                db.update(jid, lang="tr", tr_state="atlandi", stage="produce", book_name=j["title"])\n            else:\n                db.update(jid, lang=lang)\n                raise RuntimeError(f"Kitap T\xc3\xbcrk\xc3\xa7e de\xc4\x9fil ({lang}). St\xc3\xbcdyo yaln\xc4\xb1z T\xc3\xbcrk\xc3\xa7e kitap al\xc4\xb1r (\xc3\xa7eviri yok). "\n                                   "Kitap T\xc3\xbcrk\xc3\xa7eyse silip \'Kitap dili: T\xc3\xbcrk\xc3\xa7e\' se\xc3\xa7erek yeniden ekleyin.")\n            return\n\n        if stage == "translate":  # eski i\xc5\x9f (Translate kald\xc4\xb1r\xc4\xb1ld\xc4\xb1)\n            raise RuntimeError("Bu i\xc5\x9f Translate\'te \xc3\xa7evriliyordu; \xc3\xa7eviri kald\xc4\xb1r\xc4\xb1ld\xc4\xb1. \xc4\xb0\xc5\x9fi silebilirsiniz.")\n\n        if stage == "produce":\n            self.step_okuma(db.get(jid), src)\n            self.step_osm(db.get(jid))\n            j = db.get(jid)\n            if j["ok_state"] == "bitti" and j["osm_state"] == "bitti":\n                if not j["osm_title"] and j["lang"] != "tr" and not j["auto_title"]:\n                    db.update(jid, osm_title=j["title"])  # yabanc\xc4\xb1 dosya ad\xc4\xb1 Osmanl\xc4\xb1caya harf harf aktar\xc4\xb1lmaz\n                    j = db.get(jid)\n                if not j["osm_title"]:\n                    try:\n                        db.update(jid, osm_title=clients.osm_convert(j["title"]).strip())\n                    except Exception:\n                        pass\n                db.update(jid, stage="done", status="done", finished=time.time())\n                try:\n                    save_outputs(jid)\n                except Exception as e:\n                    db.update(jid, note=f"Dosyalar \xc3\xa7\xc4\xb1kt\xc4\xb1 klas\xc3\xb6r\xc3\xbcne kaydedilemedi: {str(e)[:200]}")\n                if ok_filename(j):\n                    clients.ok_clear(ok_filename(j))  # Kitap Okuma\'n\xc4\xb1n listesinden kald\xc4\xb1r\n\n    # ------------------------------------------------------------\n    def step_okuma(self, j, src):\n        jid, name, state = j["id"], j["book_name"], j["ok_state"]\n        if state == "bitti":\n            return\n        if state == "bekliyor" and j["degisti"] and time.time() - j["degisti"] < DUZELTME_BEKLEME:\n            return  # tur 2/C: kitap az \xc3\xb6nce d\xc3\xbczeltildi; art arda d\xc3\xbczeltmeler bitsin (her biri i\xc3\xa7in M4B yeniden kurulmas\xc4\xb1n)\n        if state == "bekliyor" and _baska_seslendirme_var(jid):\n            return  # tur 2/A: kitaplar kendili\xc4\x9finden geldi\xc4\x9fi i\xc3\xa7in seslendirme tek tek (say\xc4\xb1 tur 4\'te \xc3\xb6l\xc3\xa7\xc3\xbclerek)\n        if state == "bekliyor":\n            # Seslendirme de St\xc3\xbcdyo\'nun temiz metninden yap\xc4\xb1l\xc4\xb1r (\xc3\xb6n sayfalar, i\xc3\xa7indekiler ve dipnotlar hari\xc3\xa7).\n            ana = [p for p in db.all_parts(jid) if p["name"].startswith("Parca_")]\n            if not ana and jid not in self.no_orig and j["osm_state"] == "bekliyor":\n                return  # temiz metin hen\xc3\xbcz haz\xc4\xb1rlan\xc4\xb1yor\n            if ana:\n                path = parts_to_epub(ana, name, os.path.join(db.job_dir(jid), name + ".epub"))\n                clients.ok_submit(path, name + ".epub")\n                db.update(jid, ok_state="sirada")\n                return\n            if j["lang"] == "tr":\n                path, filename = src, name + os.path.splitext(j["filename"])[1].lower()\n                if filename.endswith(".txt"):  # yap\xc4\xb1\xc5\x9ft\xc4\xb1r\xc4\xb1lan metin: Kitap Okuma i\xc3\xa7in EPUB\'a \xc3\xa7evir\n                    path = txt_to_epub(src, name, os.path.join(db.job_dir(jid), name + ".epub"))\n                    filename = name + ".epub"\n            else:\n                path, filename = os.path.join(db.job_dir(jid), name + ".epub"), name + ".epub"\n            clients.ok_submit(path, filename)\n            db.update(jid, ok_state="sirada")\n            return\n        status, done, total = clients.ok_status(name)\n        upd = {}\n        if total:\n            upd.update(ok_done=done, ok_total=total)\n        if status:\n            low = status.lower()\n            if "error" in low or "hata" in low:\n                upd.update(ok_state="hata", error="Seslendirme hata verdi (Kitap Okuma).")\n            elif state != "hata":\n                upd["ok_state"] = "calisiyor" if "process" in low or "i\xc5\x9flen" in low else "sirada"\n        entry = clients.ok_library_entry(name)\n        isleniyor = bool(status) and not any(k in status.lower() for k in ("complet", "bitti", "error", "hata"))\n        # Bek\xc3\xa7i: seslendirme s\xc3\xbcr\xc3\xbcyor g\xc3\xb6r\xc3\xbcn\xc3\xbcp Kitap Okuma\'n\xc4\xb1n listesinde hi\xc3\xa7 yoksa (Kitap Okuma yeniden\n        # ba\xc5\x9flad\xc4\xb1ysa yar\xc4\xb1m kalan i\xc5\x9fi unutur) ~1 dakika sonra yeniden g\xc3\xb6nder; kald\xc4\xb1\xc4\x9f\xc4\xb1 yerden devam eder.\n        if not status and not entry and state in ("sirada", "calisiyor"):\n            self.kayip[jid] = self.kayip.get(jid, 0) + 1\n            if self.kayip[jid] >= 15:\n                self.kayip.pop(jid, None)\n                print(f"[{jid}] Kitap Okuma \'{name}\' kitab\xc4\xb1n\xc4\xb1 listesinde tutmuyor; yeniden g\xc3\xb6nderiliyor.", flush=True)\n                db.update(jid, ok_state="bekliyor")\n                return\n        else:\n            self.kayip.pop(jid, None)\n        if entry and not isleniyor:   # yeniden g\xc3\xb6nderilen kitapta eski M4B\'yi "bitti" sanma (tur 2/C)\n            upd.update(ok_state="bitti", audio=json.dumps(entry, ensure_ascii=False))\n            if j["yenile"]:            # seslendirme s\xc3\xbcrerken kitap d\xc3\xbczeltilmi\xc5\x9fti: bir kez daha g\xc3\xb6nder\n                upd.update(ok_state="bekliyor", yenile=0)\n            if upd.get("ok_total") or j["ok_total"]:\n                upd["ok_done"] = upd.get("ok_total") or j["ok_total"]\n        if upd:\n            db.update(jid, **upd)\n\n    def step_osm(self, j):\n        jid, state = j["id"], j["osm_state"]\n        if state == "bitti":\n            return\n        if state == "bekliyor" and jid not in self.no_orig:\n            # Osmanl\xc4\xb1ca ve T\xc3\xbcrk\xc3\xa7e dosyalar i\xc3\xa7in kitab\xc4\xb1n \xc4\xb0LK metni kullan\xc4\xb1l\xc4\xb1r\n            # (Kitap Okuma\'n\xc4\xb1n metni seslendirme i\xc3\xa7in de\xc4\x9fi\xc5\x9ftirilmi\xc5\x9ftir).\n            items = self.original_parts(j)\n            if items:\n                db.insert_parts(jid, items)\n                db.update(jid, osm_state="calisiyor", osm_done=0, osm_total=len(items))\n                return\n            self.no_orig.add(jid)\n            print(f"[{jid}] Kitab\xc4\xb1n ilk metni \xc3\xa7\xc4\xb1kar\xc4\xb1lamad\xc4\xb1; Kitap Okuma\'n\xc4\xb1n metni kullan\xc4\xb1lacak.", flush=True)\n        if state == "bekliyor":\n            files = sorted(glob.glob(os.path.join(TEXT_DIR, glob.escape(j["book_name"]), "Parca_*.txt")),\n                           key=_natural)\n            if not files:\n                return\n            # Kitap Okuma par\xc3\xa7alar\xc4\xb1 yazmay\xc4\xb1 bitirdi mi? Toplam biliniyorsa ona, yoksa say\xc4\xb1n\xc4\xb1n sabit kalmas\xc4\xb1na bak.\n            count, stable = self.seen.get(jid, (0, 0))\n            stable = stable + 1 if count == len(files) else 0\n            self.seen[jid] = (len(files), stable)\n            ready = (j["ok_total"] and len(files) >= j["ok_total"]) or stable >= 3\n            if not ready:\n                return\n            db.insert_parts(jid, [(os.path.basename(f), _read(f)) for f in files])\n            db.update(jid, osm_state="calisiyor", osm_done=0, osm_total=len(files))\n            self.seen.pop(jid, None)\n            return\n        if state == "calisiyor":\n            end = time.time() + OSM_BUDGET\n            pending = db.pending_parts(jid)\n            for p in pending:\n                text = (p["tr"] or "").replace("\\ue020", "").replace("\\ue021", "")   # 0.5.52\n                db.save_part(jid, p["idx"], clients.osm_convert_paras(text) if text.strip() else "")\n                if time.time() > end:\n                    return\n            db.update(jid, osm_state="bitti")\n\n\ndef _original_parts(j):\n    try:\n        notes = []\n        if j["lang"] == "tr":\n            paras, notes = textsrc.extract_full(db.source_path(j["id"], j["filename"]))\n        else:\n            return []  # T\xc3\xbcrk\xc3\xa7e olmayan kitap i\xc5\x9flenmez (Translate kald\xc4\xb1r\xc4\xb1ld\xc4\xb1)\n        paras = duzelt.duzelt(paras)  # sat\xc4\xb1r i\xc3\xa7i \xc3\xbcst bilgiler, b\xc3\xb6l\xc3\xbcnm\xc3\xbc\xc5\x9f kelimeler, \xc3\xa7\xc3\xb6p i\xc5\x9faretler, sayfa at\xc4\xb1flar\xc4\xb1\n        if sum(len(p) for p in paras) < 50:\n            return []\n        return textsrc.parts_with_notes(paras, notes)\n    except Exception:\n        traceback.print_exc()\n        return []\n\n\nWorker.original_parts = staticmethod(_original_parts)\n\n\ndef _baska_seslendirme_var(jid):\n    """Kitap Okuma her y\xc3\xbcklenen kitab\xc4\xb1 ayr\xc4\xb1 i\xc5\x9f par\xc3\xa7ac\xc4\xb1\xc4\x9f\xc4\xb1nda hemen ba\xc5\x9flat\xc4\xb1r: ayn\xc4\xb1 anda \xc3\xa7ok kitap sunucuyu bo\xc4\x9far.\n    Ba\xc5\x9fka bir etkin i\xc5\x9fin seslendirmesi s\xc3\xbcr\xc3\xbcyorsa (s\xc4\xb1rada/\xc3\xa7al\xc4\xb1\xc5\x9f\xc4\xb1yor) bu i\xc5\x9f bekler."""\n    return any(o["id"] != jid and o["ok_state"] in ("sirada", "calisiyor") for o in db.active_jobs())\n\n\ndef _ocr_ile_dil(path):\n    """Metin katman\xc4\xb1 olmayan PDF\'te kitab\xc4\xb1n i\xc3\xa7inden 3 sayfay\xc4\xb1 OCR\'lay\xc4\xb1p dili alg\xc4\xb1lar.\n    Emin olunamazsa (yeterince tan\xc4\xb1d\xc4\xb1k kelime yoksa) None d\xc3\xb6ner."""\n    try:\n        import fitz\n        from .detect import WORDS\n        n = len(fitz.open(path))\n        sayfalar = sorted({max(0, min(n - 1, k)) for k in (4, 9, 14)})\n        text = ""\n        for i in sayfalar:\n            _, items = textsrc._ocr_page((path, i))\n            text += " ".join(t for t, _ in items) + "\\n"\n        lang = detect_lang(text)\n        kelimeler = re.findall(r"[^\\W\\d_]+", text.lower())\n        if lang in WORDS and sum(1 for w in kelimeler if w in WORDS[lang]) >= 8:\n            print(f"[dil] {os.path.basename(path)}: OCR ile \'{lang}\' alg\xc4\xb1land\xc4\xb1", flush=True)\n            return lang\n    except Exception:\n        traceback.print_exc()\n    return None\n\n\nDEDPLAY_DIR = os.environ.get("DEDPLAY_DIR", "/dedplay")\nDUZELTME_BEKLEME = int(os.environ.get("DUZELTME_BEKLEME", "120"))   # saniye\nDIL_KLASORU = {"tr": "T\xc3\xbcrk\xc3\xa7e", "osm": "Osmanl\xc4\xb1ca", "iki": "T\xc3\xbcrk\xc3\xa7e-Osmanl\xc4\xb1ca"}\nBICIM_KLASORU = {"pdf": "PDF", "docx": "DOCX", "txt": "TXT", "html": "HTML"}   # EPUB\'lar\xc4\xb1 K\xc3\xbct\xc3\xbcphane yazar\n\n\ndef _bagla(src, dst):\n    """Ayn\xc4\xb1 diskteyse sabit ba\xc4\x9flant\xc4\xb1 (ayn\xc4\xb1 dosyaya ikinci ad, ek yer kaplamaz), de\xc4\x9filse kopya."""\n    if os.path.lexists(dst):\n        os.remove(dst)\n    try:\n        os.link(src, dst)\n    except OSError:\n        shutil.copy2(src, dst)\n\n\n_bicim_kilidi = threading.Lock()\n\n\ndef bicimleri_yaz(j, parts, name):\n    """PDF/DOCX/TXT/HTML -> /dedplay/<Bi\xc3\xa7im>/<Dil>/<Ad>.<uzant\xc4\xb1> (birer birer; yar\xc4\xb1m dosya g\xc3\xb6r\xc3\xbcnmesin diye ge\xc3\xa7ici adla)."""\n    from .export import build\n    with _bicim_kilidi:\n        for fmt, bk in BICIM_KLASORU.items():\n            for variant, dk in DIL_KLASORU.items():\n                data, _, _ = build(j, parts, fmt, variant)\n                d = os.path.join(DEDPLAY_DIR, bk, dk)\n                os.makedirs(d, exist_ok=True)\n                hedef = os.path.join(d, f"{name}.{fmt}")\n                gecici = f"{hedef}.{threading.get_ident()}.tmp"\n                with open(gecici, "wb") as f:\n                    f.write(data)\n                os.replace(gecici, hedef)\n\n\ndef bicimleri_simdi_yaz(jid):\n    """0.5.21: bi\xc3\xa7imler sesi beklemez. St\xc3\xbcdyo i\xc5\x9fi a\xc3\xa7\xc4\xb1l\xc4\xb1nca ve kitap d\xc3\xbczeltilince arka planda hemen yaz\xc4\xb1l\xc4\xb1r; MP3/M4B\n    seslendirme bitince eklenir (save_outputs)."""\n    def calis():\n        try:\n            j = db.get(jid)\n            if not j or j["osm_state"] != "bitti" or not os.path.isdir(DEDPLAY_DIR):\n                return\n            parts = db.all_parts(jid)\n            if parts:\n                bicimleri_yaz(j, parts, (j["book_name"] or j["title"]).replace("/", "-"))\n                print(f"[bicim] i\xc5\x9f {jid}: PDF/DOCX/TXT/HTML yaz\xc4\xb1ld\xc4\xb1", flush=True)\n        except Exception as e:\n            traceback.print_exc()\n            db.update(jid, note=f"Bi\xc3\xa7imler yaz\xc4\xb1lamad\xc4\xb1: {str(e)[:200]}")\n    threading.Thread(target=calis, daemon=True, name=f"bicim-{jid}").start()\n\n\ndef _guvenli_ad(ad):\n    """Dosya ad\xc4\xb1 olarak g\xc3\xbcvenli mi (bo\xc5\x9f, \'.\', \'..\' ya da klas\xc3\xb6r ay\xc4\xb1rac\xc4\xb1 de\xc4\x9fil)."""\n    return bool(ad) and ad.strip() not in ("", ".", "..") and "/" not in ad and "\\x00" not in ad\n\n\ndef _icinde_mi(yol, kok):\n    return os.path.realpath(yol).startswith(os.path.realpath(kok).rstrip("/") + "/")\n\n\ndef ciktilari_sil(j):\n    """0.5.39: kitap silinirken "dosyalar\xc4\xb1n\xc4\xb1 da sil" se\xc3\xa7ilirse kitab\xc4\xb1n /dedplay\'deki dosyalar\xc4\xb1 silinir: PDF/DOCX/TXT/HTML\n    (3 dil), MP3/<Ad>/, M4B/<Ad>.m4b ve <Ad> - n.m4b, seslendirmenin \xc3\xa7al\xc4\xb1\xc5\x9fma klas\xc3\xb6r\xc3\xbc .seslendirme/<Ad>/. Yaln\xc4\xb1z bu kitab\xc4\xb1n\n    ad\xc4\xb1yla birebir e\xc5\x9fle\xc5\x9fenler; ba\xc5\x9fka kitaba dokunulmaz. D\xc3\xb6nen: silinen yollar."""\n    silinen = []\n    if not j or not os.path.isdir(DEDPLAY_DIR):\n        return silinen\n    name = (j["book_name"] or j["title"] or "").replace("/", "-")\n    if not _guvenli_ad(name):\n        return silinen\n\n    def dosya(yol, kok=DEDPLAY_DIR):\n        if os.path.lexists(yol) and not os.path.isdir(yol) and _icinde_mi(yol, kok):\n            os.remove(yol)\n            silinen.append(yol)\n\n    def klasor(yol, kok=DEDPLAY_DIR):\n        if os.path.isdir(yol) and not os.path.islink(yol) and _icinde_mi(yol, kok):\n            shutil.rmtree(yol, ignore_errors=True)\n            silinen.append(yol)\n\n    for fmt, bk in BICIM_KLASORU.items():\n        for dk in DIL_KLASORU.values():\n            dosya(os.path.join(DEDPLAY_DIR, bk, dk, f"{name}.{fmt}"))\n    klasor(os.path.join(DEDPLAY_DIR, "MP3", name))\n    md = os.path.join(DEDPLAY_DIR, "M4B")\n    if os.path.isdir(md):\n        for f in sorted(os.listdir(md)):\n            if f == name + ".m4b" or re.fullmatch(re.escape(name) + r" - \\d+\\.m4b", f):\n                dosya(os.path.join(md, f))\n    ses = j["book_name"] or name   # Kitap Okuma\'n\xc4\xb1n klas\xc3\xb6r\xc3\xbc (g\xc3\xb6nderilen dosyan\xc4\xb1n ad\xc4\xb1 = book_name)\n    if _guvenli_ad(ses) and os.path.isdir(OUTPUT_DIR):\n        klasor(os.path.join(OUTPUT_DIR, ses), OUTPUT_DIR)\n    return silinen\n\n\ndef save_outputs_yeni(j, parts, name):\n    """Tur 3: /dedplay alt\xc4\xb1nda bi\xc3\xa7im/dil/kitap ad\xc4\xb1 d\xc3\xbczeni:\n    PDF/T\xc3\xbcrk\xc3\xa7e/Kitap.pdf, PDF/Osmanl\xc4\xb1ca/\xe2\x80\xa6, PDF/T\xc3\xbcrk\xc3\xa7e-Osmanl\xc4\xb1ca/\xe2\x80\xa6 (DOCX, TXT, HTML ayn\xc4\xb1); MP3/Kitap/Kitap - 001.mp3;\n    M4B/Kitap.m4b (b\xc3\xbcy\xc3\xbck kitapta Kitap - 1.m4b, - 2\xe2\x80\xa6). Kitap Okuma\'n\xc4\xb1n kendi dosyalar\xc4\xb1 yerinde kal\xc4\xb1r (d\xc3\xbczeltmede yaln\xc4\xb1z\n    de\xc4\x9fi\xc5\x9fen b\xc3\xb6l\xc3\xbcm yeniden okunsun diye)."""\n    bicimleri_yaz(j, parts, name)\n    kaynak = os.path.join(OUTPUT_DIR, j["book_name"] or name)\n    mp3s = sorted(glob.glob(os.path.join(glob.escape(kaynak), "Parca_*.mp3")) +\n                  glob.glob(os.path.join(glob.escape(kaynak), "Bolum_*.mp3")), key=_natural)\n    if mp3s:\n        mdir = os.path.join(DEDPLAY_DIR, "MP3", name)\n        shutil.rmtree(mdir, ignore_errors=True)\n        os.makedirs(mdir)\n        width = max(3, len(str(len(mp3s))))\n        for n, src in enumerate(mp3s, 1):\n            dst = os.path.join(mdir, f"{name} - {n:0{width}d}.mp3")\n            _bagla(src, dst)\n            _tag_mp3(dst, name, n, len(mp3s), width)\n    m4bs = sorted(glob.glob(os.path.join(glob.escape(kaynak), "*.m4b")), key=_natural)\n    if m4bs:\n        md = os.path.join(DEDPLAY_DIR, "M4B")\n        os.makedirs(md, exist_ok=True)\n        for eski in glob.glob(os.path.join(glob.escape(md), glob.escape(name) + "*.m4b")):\n            if os.path.basename(eski) == name + ".m4b" or re.fullmatch(re.escape(name) + r" - \\d+\\.m4b", os.path.basename(eski)):\n                os.remove(eski)\n        for i, src in enumerate(m4bs, 1):\n            hedef = os.path.join(md, f"{name}.m4b" if len(m4bs) == 1 else f"{name} - {i}.m4b")\n            _bagla(src, hedef + ".tmp")\n            os.replace(hedef + ".tmp", hedef)\n\n\ndef save_outputs(job_id):\n    """Biten kitab\xc4\xb1n dosyalar\xc4\xb1n\xc4\xb1 \xc3\xa7\xc4\xb1kt\xc4\xb1 klas\xc3\xb6r\xc3\xbcne kaydeder: M4B kitap klas\xc3\xb6r\xc3\xbcn\xc3\xbcn \xc3\xbcst\xc3\xbcnde kal\xc4\xb1r,\n    di\xc4\x9fer dosyalar bi\xc3\xa7imlerine g\xc3\xb6re alt klas\xc3\xb6rlere (EPUB, PDF, Word, HTML, TXT) ayr\xc4\xb1l\xc4\xb1r."""\n    if not os.path.isdir(OUTPUT_DIR):\n        raise RuntimeError("\xc3\x87\xc4\xb1kt\xc4\xb1 klas\xc3\xb6r\xc3\xbc ba\xc4\x9fl\xc4\xb1 de\xc4\x9fil (docker-compose\'da /cikti).")\n    from .export import build\n    j = db.get(job_id)\n    if not j["osm_title"] and j["lang"] != "tr" and not j["auto_title"]:\n        db.update(job_id, osm_title=j["title"])\n        j = db.get(job_id)\n    if not j["osm_title"]:\n        try:\n            db.update(job_id, osm_title=clients.osm_convert(j["title"]).strip())\n            j = db.get(job_id)\n        except Exception:\n            pass\n    parts = db.all_parts(job_id)\n    if not parts:\n        raise RuntimeError("Metin par\xc3\xa7alar\xc4\xb1 yok.")\n    name = (j["book_name"] or j["title"]).replace("/", "-")\n    if os.path.isdir(DEDPLAY_DIR):          # tur 3: yeni \xc3\xa7\xc4\xb1kt\xc4\xb1 d\xc3\xbczeni\n        save_outputs_yeni(j, parts, name)\n        db.update(job_id, saved=name, note=None)\n        return name\n    folder = os.path.join(OUTPUT_DIR, name)\n    os.makedirs(folder, exist_ok=True)\n    subdir = {"epub": "EPUB", "pdf": "PDF", "docx": "Word", "html": "HTML", "txt": "TXT"}\n    # Eski s\xc3\xbcr\xc3\xbcm\xc3\xbcn klas\xc3\xb6r\xc3\xbcn \xc3\xbcst\xc3\xbcne b\xc4\xb1rakt\xc4\xb1\xc4\x9f\xc4\xb1 da\xc4\x9f\xc4\xb1n\xc4\xb1k dosyalar\xc4\xb1 temizle (M4B ve MP3\'e dokunma)\n    for f in os.listdir(folder):\n        fp = os.path.join(folder, f)\n        if os.path.isfile(fp) and os.path.splitext(f)[1].lower().lstrip(".") in subdir:\n            os.remove(fp)\n    for fmt, sd in subdir.items():\n        os.makedirs(os.path.join(folder, sd), exist_ok=True)\n        for variant in ("tr", "osm", "iki"):\n            data, _, fname = build(j, parts, fmt, variant)\n            with open(os.path.join(folder, sd, fname.replace("/", "-")), "wb") as f:\n                f.write(data)\n    # MP3 par\xc3\xa7alar\xc4\xb1: kitap ad\xc4\xb1yla, ek yer kaplamadan (ayn\xc4\xb1 dosyaya ikinci ad = sabit ba\xc4\x9flant\xc4\xb1)\n    mp3s = sorted(glob.glob(os.path.join(glob.escape(folder), "Parca_*.mp3")) +\n                  glob.glob(os.path.join(glob.escape(folder), "Bolum_*.mp3")), key=_natural)\n    if mp3s:\n        mdir = os.path.join(folder, "MP3")\n        shutil.rmtree(mdir, ignore_errors=True)\n        os.makedirs(mdir)\n        open(os.path.join(mdir, ".ignore"), "w").close()  # Audiobookshelf bu klas\xc3\xb6r\xc3\xbc taramas\xc4\xb1n\n        total = max(_natural(x) for x in mp3s)\n        width = max(3, len(str(total)))\n        for src in mp3s:\n            n = _natural(src)\n            dst = os.path.join(mdir, f"{name} - {n:0{width}d}.mp3")\n            try:\n                os.link(src, dst)\n            except OSError:\n                shutil.copy2(src, dst)\n            _tag_mp3(dst, name, n, total, width)\n        # MP3 klas\xc3\xb6r\xc3\xbcndeki kopyalar ayn\xc4\xb1 dosyan\xc4\xb1n ikinci ad\xc4\xb1; \xc3\xbcstteki Parca_ adlar\xc4\xb1 art\xc4\xb1k gereksiz.\n        for src in mp3s:\n            try:\n                os.remove(src)\n            except OSError:\n                pass\n    db.update(job_id, saved=name, note=None)\n    return name\n\n\ndef _tag_mp3(path, book, n, total, width):\n    """MP3\'\xc3\xbcn i\xc3\xa7ine kitap bilgisini yazar (alb\xc3\xbcm = kitap ad\xc4\xb1, s\xc4\xb1ra numaras\xc4\xb1)."""\n    try:\n        from mutagen.easyid3 import EasyID3\n        from mutagen.id3 import ID3NoHeaderError\n        try:\n            t = EasyID3(path)\n        except ID3NoHeaderError:\n            t = EasyID3()\n        t["album"] = book\n        t["title"] = f"{book} - {n:0{width}d}"\n        t["tracknumber"] = f"{n}/{total}"\n        t["artist"] = "Dedplay"\n        t["genre"] = "Audiobook"\n        t.save(path)\n    except Exception:\n        pass\n\n\ndef resume(job_id):\n    """Hata veren ya da duran bir i\xc5\x9fi kald\xc4\xb1\xc4\x9f\xc4\xb1 yerden s\xc3\xbcrd\xc3\xbcr\xc3\xbcr."""\n    j = db.get(job_id)\n    if not j:\n        return\n    upd = {"status": "active", "error": None}\n    if j["ok_state"] == "hata":\n        upd["ok_state"] = "bekliyor"  # yeniden g\xc3\xb6nderilir; Kitap Okuma biten par\xc3\xa7alar\xc4\xb1 atlar\n    if j["osm_state"] == "hata":\n        upd["osm_state"] = "calisiyor"\n    db.update(job_id, **upd)\n\n\nworker = Worker()\n', 'kutuphane/main.py': b'"""Dedplay K\xc3\xbct\xc3\xbcphane: kitap arama, ekleme, EPUB \xc3\xbcretme (ve ileride okuma/d\xc3\xbczeltme)."""\nimport os\nimport re\nfrom urllib.parse import quote\n\nimport requests\nfrom fastapi import FastAPI, HTTPException\nfrom fastapi.responses import FileResponse, HTMLResponse, Response\nfrom pydantic import BaseModel\n\nfrom fastapi import File, UploadFile\n\nfrom . import cikti, depo, epub, epubcheck, katalog, kaynak, osmanlica, yz\nfrom . import kitap as K\n\nKAYNAK = os.environ.get("KAYNAK_DIR", "/kaynak")\nUZANTILAR = (".pdf", ".epub", ".docx", ".txt")\n\nSURUM = "0.5.60"\nSTATIK = os.path.join(os.path.dirname(__file__), "static")\nHOST = "http://host.docker.internal"\nSERVISLER = {\n    "Seslendirme (Kitap Okuma)": os.environ.get("OKUMA_URL", f"{HOST}:8020") + "/status",\n    "Osmanl\xc4\xb1ca": os.environ.get("OSMANLICA_URL", f"{HOST}:8089") + "/",\n}\n\napp = FastAPI(title="Dedplay St\xc3\xbcdyo", version=SURUM)\n\n\n@app.on_event("startup")\ndef _basla():\n    os.makedirs(depo.KITAPLAR, exist_ok=True)\n    depo.baslat()\n\n\n@app.get("/", response_class=HTMLResponse)\ndef ana():\n    return open(os.path.join(STATIK, "index.html"), encoding="utf-8").read()\n\n\n@app.get("/api/durum")\ndef durum():\n    s = {}\n    for ad, url in SERVISLER.items():\n        try:\n            s[ad] = requests.get(url, timeout=3).status_code < 500\n        except Exception:\n            s[ad] = False\n    kat = os.path.join(depo.VERI, "openiti", "katalog.csv")\n    return {"surum": SURUM, "epubcheck": epubcheck.var_mi(), "servisler": s, "cikti": os.path.isdir(cikti.CIKTI),\n            "katalog": os.path.exists(kat), "katalog_tarih": int(os.path.getmtime(kat)) if os.path.exists(kat) else None}\n\n\n# ---------------- OpenITI katalogu ----------------\n@app.get("/api/katalog/ara")\ndef katalog_ara(q: str, azami: int = 50):\n    try:\n        sonuc = katalog.ara(depo.VERI, q, min(max(azami, 1), 200))\n    except Exception as e:\n        raise HTTPException(503, f"Katalog y\xc3\xbcklenemedi: {e}")\n    ekli = {k["kimlik"] for k in depo.liste()}\n    for s in sonuc:\n        s["ekli"] = s["versionUri"] in ekli\n    return sonuc\n\n\n@app.post("/api/katalog/yenile")\ndef katalog_yenile():\n    try:\n        katalog.indir(depo.VERI)\n        return {"ok": True, "eser": len(katalog.yukle(depo.VERI, indirmeye_izin=False))}\n    except Exception as e:\n        raise HTTPException(503, f"Katalog indirilemedi: {e}")\n\n\nclass OpenitiEkle(BaseModel):\n    version_uri: str\n\n\n@app.post("/api/kitaplar/openiti")\ndef openiti_ekle(g: OpenitiEkle):\n    satir = katalog.bul(depo.VERI, g.version_uri)\n    if not satir:\n        raise HTTPException(404, "Katalogda b\xc3\xb6yle bir eser yok")\n    kid = g.version_uri\n    depo.klasor(kid)  # kimlik denetimi\n    import time\n    ilk = depo.durum_oku(kid)\n    depo.is_ekle("openiti", kid, g.version_uri, tur="openiti", kaynak_kimlik=g.version_uri,\n                 baslik=ilk.get("baslik") or satir["title_ar"].split("::")[0].strip(),\n                 baslik_asil=satir["title_ar"].split("::")[0].strip(),\n                 yazar=ilk.get("yazar") or satir["author_ar"].split("::")[0].strip(),\n                 eklendi=ilk.get("eklendi") or int(time.time()))\n    return {"ok": True, "kimlik": kid}\n\n\n# ---------------- Elindeki kitaplar: sunucu ar\xc5\x9fivi ve y\xc3\xbckleme ----------------\ndef _guvenli(yol):\n    tam = os.path.realpath(os.path.join(KAYNAK, (yol or "").lstrip("/")))\n    if tam != os.path.realpath(KAYNAK) and not tam.startswith(os.path.realpath(KAYNAK) + os.sep):\n        raise HTTPException(400, "Ge\xc3\xa7ersiz yol")\n    return tam\n\n\n@app.get("/api/kaynak")\ndef kaynak_gez(yol: str = ""):\n    tam = _guvenli(yol)\n    if not os.path.isdir(tam):\n        raise HTTPException(404, "Klas\xc3\xb6r bulunamad\xc4\xb1 (ar\xc5\x9fiv ba\xc4\x9fl\xc4\xb1 m\xc4\xb1?)")\n    klasor, dosya = [], []\n    for ad in sorted(os.listdir(tam), key=lambda x: x.lower()):\n        if ad.startswith("."):\n            continue\n        p = os.path.join(tam, ad)\n        if os.path.isdir(p):\n            klasor.append(ad)\n        elif ad.lower().endswith(UZANTILAR):\n            dosya.append({"ad": ad, "boyut": os.path.getsize(p)})\n    ekli = {k["kimlik"] for k in depo.liste()}\n    for f in dosya:\n        f["ekli"] = kaynak.kimlik_uret(os.path.join(tam, f["ad"])) in ekli\n    return {"yol": os.path.relpath(tam, KAYNAK) if tam != os.path.realpath(KAYNAK) else "", "klasor": klasor, "dosya": dosya}\n\n\ndef _ayni_adli_kitap(gorunen_ad):\n    """0.5.26: dosya ad\xc4\xb1 (uzant\xc4\xb1s\xc4\xb1z) listedeki bir kitab\xc4\xb1n kaynak dosyas\xc4\xb1n\xc4\xb1n ad\xc4\xb1yla birebir ayn\xc4\xb1ysa o kitab\xc4\xb1n kimli\xc4\x9fi:\n    kitap nereden verilirse verilsin ayn\xc4\xb1 kay\xc4\xb1t, ayn\xc4\xb1 St\xc3\xbcdyo i\xc5\x9fi, bi\xc3\xa7imler \xc3\xbczerine yaz\xc4\xb1l\xc4\xb1r."""\n    try:\n        from .katalog import sade\n    except ImportError:\n        from kutuphane.katalog import sade\n    hedef = sade(os.path.splitext(os.path.basename(gorunen_ad))[0])\n    for k in depo.liste():\n        yol = depo.durum_oku(k["kimlik"]).get("kaynak_kimlik") or ""\n        if os.path.isabs(yol) and sade(os.path.splitext(os.path.basename(yol))[0]) == hedef:\n            return k["kimlik"]\n    return None\n\n\ndef _dosya_isi(yol, gorunen_ad):\n    import time\n    kid = kaynak.kimlik_uret(yol)\n    if not depo.durum_oku(kid):  # 0.5.26: ayn\xc4\xb1 adl\xc4\xb1 kitap ba\xc5\x9fka yerden verildiyse o kitap g\xc3\xbcncellenir\n        kid = _ayni_adli_kitap(gorunen_ad) or kid\n    ilk = depo.durum_oku(kid)\n    baslik, yazar = kaynak._dosya_adindan(gorunen_ad)\n    depo.is_ekle("dosya", kid, yol, tur="dosya", kaynak_kimlik=yol, baslik=ilk.get("baslik") or baslik,\n                 baslik_asil=ilk.get("baslik_asil") or baslik, yazar=ilk.get("yazar") or yazar,\n                 eklendi=ilk.get("eklendi") or int(time.time()))\n    return {"ok": True, "kimlik": kid}\n\n\nclass SunucuDosyasi(BaseModel):\n    yol: str\n\n\n@app.post("/api/kitaplar/sunucudan")\ndef sunucudan_ekle(g: SunucuDosyasi):\n    tam = _guvenli(g.yol)\n    if not os.path.isfile(tam) or not tam.lower().endswith(UZANTILAR):\n        raise HTTPException(400, "Sadece PDF, EPUB, DOCX ve TXT dosyalar\xc4\xb1 eklenebilir")\n    return _dosya_isi(tam, os.path.basename(tam))\n\n\nclass MetinIstegi(BaseModel):\n    baslik: str\n    metin: str\n\n\n@app.post("/api/kitaplar/metin")\ndef metin_ekle(g: MetinIstegi):\n    """Yap\xc4\xb1\xc5\x9ft\xc4\xb1r\xc4\xb1lan metin: TXT dosyas\xc4\xb1 olarak kaydedilir, y\xc3\xbcklenen kitap gibi i\xc5\x9flenir (temizlik, okuma ekran\xc4\xb1)."""\n    baslik = re.sub(r"[\\\\/:*?\\"<>|]+", " ", (g.baslik or "").strip())[:120].strip() or "Metin"\n    if len(g.metin.strip()) < 20:\n        raise HTTPException(400, "Metin \xc3\xa7ok k\xc4\xb1sa")\n    klasor = os.path.join(depo.VERI, "yuklenen")\n    os.makedirs(klasor, exist_ok=True)\n    hedef = os.path.join(klasor, baslik + ".txt")\n    with open(hedef, "w", encoding="utf-8") as f:\n        f.write(g.metin)\n    return _dosya_isi(hedef, baslik + ".txt")\n\n\n@app.post("/api/kitaplar/yukle")\ndef yukle(dosya: UploadFile = File(...)):\n    ad = os.path.basename(dosya.filename or "kitap")\n    if not ad.lower().endswith(UZANTILAR):\n        raise HTTPException(400, "Sadece PDF, EPUB, DOCX ve TXT dosyalar\xc4\xb1 y\xc3\xbcklenebilir")\n    klasor = os.path.join(depo.VERI, "yuklenen")\n    os.makedirs(klasor, exist_ok=True)\n    hedef = os.path.join(klasor, ad)\n    with open(hedef + ".tmp", "wb") as f:\n        while True:\n            parca = dosya.file.read(1024 * 1024)\n            if not parca:\n                break\n            f.write(parca)\n    os.replace(hedef + ".tmp", hedef)\n    return _dosya_isi(hedef, ad)\n\n\n@app.post("/api/kitaplar/{kid}/osmanlica")\ndef osmanlicayi_yenile(kid: str):\n    kit = _kitap(kid)\n    if not any(b["metin"].get("tr") for b in kit["bloklar"]):\n        raise HTTPException(400, "Bu kitapta hen\xc3\xbcz T\xc3\xbcrk\xc3\xa7e metin yok")\n    depo.is_ekle("osmanlica", kid, tur="epub")\n    return {"ok": True}\n\n\n# ---------------- Kitaplar ----------------\n@app.get("/api/rapor")\ndef toplu_rapor(uzun: int = 0):\n    """0.5.23: b\xc3\xbct\xc3\xbcn kitaplar\xc4\xb1n raporlar\xc4\xb1n\xc4\xb1n \xc3\xb6zeti (d\xc3\xbcz metin; taray\xc4\xb1c\xc4\xb1da a\xc3\xa7\xc4\xb1l\xc4\xb1p kaydedilebilir)."""\n    from . import rapor\n    return Response(rapor.toplu(kisa=not uzun), media_type="text/plain; charset=utf-8")\n\n\n@app.get("/api/kitaplar/{kid}/rapor")\ndef kitap_raporu(kid: str):\n    yol = os.path.join(depo.klasor(kid), "rapor.txt")\n    if not os.path.exists(yol):\n        raise HTTPException(404, "Bu kitab\xc4\xb1n raporu yok (0.5.23\'ten \xc3\xb6nce i\xc5\x9flenmi\xc5\x9f; yeniden y\xc3\xbcklenince olu\xc5\x9fur)")\n    return Response(open(yol, encoding="utf-8").read(), media_type="text/plain; charset=utf-8")\n\n\n@app.get("/api/kitaplar")\ndef kitaplar():\n    return depo.liste()\n\n\ndef _kitap(kid):\n    try:\n        yol = depo.kitap_yolu(kid)\n    except ValueError:\n        raise HTTPException(400, "Ge\xc3\xa7ersiz kitap kimli\xc4\x9fi")\n    if not os.path.exists(yol):\n        raise HTTPException(404, "Kitap hen\xc3\xbcz haz\xc4\xb1r de\xc4\x9fil")\n    return K.yukle(yol)\n\n\n@app.get("/api/kitaplar/{kid}")\ndef kitap_ayrinti(kid: str):\n    d = depo.durum_oku(kid) if depo.KIMLIK.match(kid) else None\n    if not d:\n        raise HTTPException(404, "B\xc3\xb6yle bir kitap yok")\n    out = {"kimlik": kid, "durum": d}\n    if os.path.exists(depo.kitap_yolu(kid)):\n        kit = K.yukle(depo.kitap_yolu(kid))\n        bl = kit["bloklar"]\n        out["kunye"] = kit["kunye"]\n        out["diller"] = K.diller(kit)\n        out["fihrist"] = [{"id": b["id"], "seviye": b.get("seviye", 1), "metin": b["metin"]}\n                          for b in bl if b["tur"] == "baslik"]\n        out["istatistik"] = {"blok": len(bl), "baslik": len(out["fihrist"]),\n                             "sayfa": sum(len(b.get("sayfalar", [])) for b in bl),\n                             "kelime": sum(len((b["metin"].get(kit["kunye"].get("asil_dil", "ar")) or "").split())\n                                           for b in bl)}\n    return out\n\n\nclass Kunye(BaseModel):\n    baslik_tr: str | None = None\n    yazar_tr: str | None = None\n\n\n@app.patch("/api/kitaplar/{kid}/kunye")\ndef kunye_duzelt(kid: str, k: Kunye):\n    kit = _kitap(kid)\n    degisti = False\n    for alan, deger in (("baslik", k.baslik_tr), ("yazar", k.yazar_tr)):\n        if deger is not None and deger.strip() != kit["kunye"].get(alan, {}).get("tr", ""):\n            kit["kunye"].setdefault(alan, {})["tr"] = deger.strip()\n            kit["kunye"][alan]["elle"] = True\n            kit["kunye"][alan].pop("osm", None)  # Osmanl\xc4\xb1cas\xc4\xb1 yeniden \xc3\xa7evrilecek\n            degisti = True\n    K.kaydet(kit, depo.kitap_yolu(kid))\n    tr_asilli = kit["kunye"].get("asil_dil") == "tr"\n    depo.is_ekle("kunye" if (degisti and tr_asilli) else "epub", kid, tur="epub")\n    return {"ok": True}\n\n\n@app.post("/api/kitaplar/{kid}/yeniden")\ndef yeniden(kid: str):\n    _kitap(kid)\n    depo.is_ekle("epub", kid, tur="epub")\n    return {"ok": True}\n\n\n@app.post("/api/kitaplar/{kid}/kaynaktan")\ndef kaynaktan_yeniden(kid: str):\n    """0.5.26: kitab\xc4\xb1 kayna\xc4\x9f\xc4\xb1ndan ba\xc5\x9ftan i\xc5\x9fler (temizlik, Osmanl\xc4\xb1ca, EPUB\'lar; St\xc3\xbcdyo i\xc5\x9fi yenilenir).\n    Okuma ekran\xc4\xb1ndaki metin d\xc3\xbczeltmeleri korunmaz (\xc3\xb6nceki kitap.json yedeklenir); elle d\xc3\xbczeltilen ad/yazar korunur."""\n    _kitap(kid)\n    d = depo.durum_oku(kid)\n    yol = d.get("kaynak_kimlik")\n    if not yol:\n        raise HTTPException(400, "Kitab\xc4\xb1n kayna\xc4\x9f\xc4\xb1 kay\xc4\xb1tl\xc4\xb1 de\xc4\x9fil")\n    if os.path.isabs(yol):\n        if not os.path.isfile(yol):\n            raise HTTPException(404, "Kaynak dosya bulunamad\xc4\xb1: " + yol)\n        depo.is_ekle("dosya", kid, yol, tur="dosya")\n    else:  # OpenITI: indirilmi\xc5\x9f metinden yeniden\n        depo.is_ekle("openiti", kid, yol, tur="openiti")\n    return {"ok": True}\n\n\n@app.get("/api/kitaplar/{kid}/epub/{dosya}")\ndef epub_indir(kid: str, dosya: str):\n    d = depo.durum_oku(kid) if depo.KIMLIK.match(kid) else {}\n    if dosya not in {e["dosya"] for e in d.get("epublar") or []}:\n        raise HTTPException(404, "B\xc3\xb6yle bir EPUB yok")\n    yol = os.path.join(depo.klasor(kid), "epub", dosya)\n    if not os.path.exists(yol):\n        raise HTTPException(404, "Dosya bulunamad\xc4\xb1 (yeniden \xc3\xbcretiliyor olabilir)")\n    return FileResponse(yol, media_type="application/epub+zip",\n                        headers={"Content-Disposition": f"attachment; filename*=UTF-8\'\'{quote(dosya)}"})\n\n\n@app.get("/api/kitaplar/{kid}/paket")\ndef paket(kid: str):\n    """0.5.50: Mac\'teki Dedplay Haz\xc4\xb1rl\xc4\xb1k i\xc3\xa7in kitap paketi (zip). Kitaba ve dosyalara dokunmaz (salt okur).\n    \xc4\xb0\xc3\xa7inde: paket.json, kaynak/<as\xc4\xb1l dosya>, ocr_onbellek/<klas\xc3\xb6r>/s0001.json\xe2\x80\xa6 (Surya\'n\xc4\xb1n ham sat\xc4\xb1rlar\xc4\xb1: Mac OCR yapmadan\n    kitab\xc4\xb1 ayn\xc4\xb1 kodla yeniden kurar), kitap.json ve rapor.json (kar\xc5\x9f\xc4\xb1la\xc5\x9ft\xc4\xb1rma i\xc3\xa7in)."""\n    import json\n    import tempfile\n    import zipfile\n    from starlette.background import BackgroundTask\n    d = depo.durum_oku(kid) if depo.KIMLIK.match(kid) else None\n    if not d:\n        raise HTTPException(404, "B\xc3\xb6yle bir kitap yok")\n    yol = d.get("kaynak_kimlik") or ""\n    if not os.path.isabs(yol) or not os.path.isfile(yol):\n        raise HTTPException(404, "Kitab\xc4\xb1n kaynak dosyas\xc4\xb1 yok (OpenITI ya da silinmi\xc5\x9f): " + (yol or "-"))\n    onb = kaynak._ocr_onbellek_klasoru(yol)\n    ocr = sorted(os.listdir(onb)) if onb and os.path.isdir(onb) else []\n    bilgi = {"paket": 1, "studyo": SURUM, "kimlik": kid, "baslik": d.get("baslik"), "yazar": d.get("yazar"),\n             "kaynak_ad": os.path.basename(yol), "ocr_klasoru": os.path.basename(onb) if onb else None,\n             "ocr_dosya": len(ocr), "surya_anahtari": kaynak._surya_anahtari()}\n    fd, gecici = tempfile.mkstemp(suffix=".zip")\n    os.close(fd)\n    try:\n        with zipfile.ZipFile(gecici, "w", zipfile.ZIP_DEFLATED) as z:\n            z.writestr("paket.json", json.dumps(bilgi, ensure_ascii=False, indent=1))\n            z.write(yol, "kaynak/" + os.path.basename(yol), compress_type=zipfile.ZIP_STORED)\n            for ad in ocr:\n                z.write(os.path.join(onb, ad), f"ocr_onbellek/{os.path.basename(onb)}/{ad}")\n            for ad in ("kitap.json", "rapor.json"):\n                if os.path.isfile(os.path.join(depo.klasor(kid), ad)):\n                    z.write(os.path.join(depo.klasor(kid), ad), ad)\n    except Exception:\n        os.remove(gecici)\n        raise\n    return FileResponse(gecici, media_type="application/zip", background=BackgroundTask(os.remove, gecici),\n                        headers={"Content-Disposition": f"attachment; filename*=UTF-8\'\'{quote(kid)}.zip"})\n\n\n@app.delete("/api/kitaplar/{kid}")\ndef kitap_sil(kid: str, dosyalar: bool = False):\n    d = depo.durum_oku(kid) if depo.KIMLIK.match(kid) else None\n    if not d:\n        raise HTTPException(404, "B\xc3\xb6yle bir kitap yok")\n    silinen = 0\n    if dosyalar:  # 0.5.39: "dosyalar\xc4\xb1n\xc4\xb1 da sil": EPUB\'lar burada, \xc3\xb6teki bi\xc3\xa7imler ve sesler St\xc3\xbcdyo i\xc5\x9fiyle a\xc5\x9fa\xc4\x9f\xc4\xb1da\n        kit = None\n        try:\n            yol = depo.kitap_yolu(kid)\n            kit = K.yukle(yol) if os.path.exists(yol) else None\n        except Exception:\n            pass\n        try:\n            silinen += len(cikti.epublari_sil(kit, d.get("cikti")))\n        except Exception as e:\n            print(f"EPUB\'lar silinemedi ({kid}): {type(e).__name__}: {e}", flush=True)\n    is_no = (d.get("studyo") or {}).get("is")\n    if is_no:  # 0.5.21: kitab\xc4\xb1n St\xc3\xbcdyo i\xc5\x9fi (seslendirme s\xc4\xb1ras\xc4\xb1) de silinir; dosyalar yaln\xc4\xb1z istenirse (0.5.39)\n        try:\n            from app.main import delete_job\n            silinen += (delete_job(int(is_no), dosyalar=dosyalar) or {}).get("silinen", 0)\n        except Exception as e:\n            print(f"St\xc3\xbcdyo i\xc5\x9fi {is_no} silinemedi: {type(e).__name__}: {e}", flush=True)\n    # 0.5.19: s\xc4\xb1rada bekleyen kitap hemen silinir; i\xc5\x9fi \xc3\xa7al\xc4\xb1\xc5\x9fan kitab\xc4\xb1n i\xc5\x9fi durdurulup kitap ard\xc4\xb1ndan silinir\n    return {"ok": True, "durum": depo.sil_iste(kid), "silinen": silinen}\n\n\n@app.post("/api/kitaplar/{kid}/studyo")\ndef studyoya_gonder(kid: str):\n    kit = _kitap(kid)\n    d = depo.durum_oku(kid)\n    if d.get("asama") not in ("haz\xc4\xb1r", "hata") or not d.get("epublar"):\n        raise HTTPException(409, "Kitap hen\xc3\xbcz haz\xc4\xb1r de\xc4\x9fil")\n    if "tr" not in K.diller(kit):\n        raise HTTPException(409, "Kitab\xc4\xb1n T\xc3\xbcrk\xc3\xa7esi yok: \xc3\xb6nce T\xc3\xbcrk\xc3\xa7eye \xc3\xa7evrilmeli (\'T\xc3\xbcrk\xc3\xa7eye \xc3\xa7evir ve St\xc3\xbcdyo\'ya g\xc3\xb6nder\')")\n    try:   # tur 2/D: kitab\xc4\xb1n i\xc5\x9fi varsa o yenilenir (eskiden her seferinde yeni i\xc5\x9f a\xc3\xa7\xc4\xb1l\xc4\xb1yordu)\n        eski = (d.get("studyo") or {}).get("is")\n        sonuc = cikti.studyoyu_guncelle(kit, eski) if eski and cikti.studyo_isi_var(eski) else cikti.studyoya_gonder(kit)\n    except requests.RequestException as e:\n        raise HTTPException(503, f"St\xc3\xbcdyo\'ya ula\xc5\x9f\xc4\xb1lamad\xc4\xb1: {type(e).__name__}")\n    except RuntimeError as e:\n        raise HTTPException(502, str(e))\n    depo.durum_yaz(kid, studyo=sonuc, studyo_uyari=None)\n    return sonuc\n\n\n# ---------------- 0.5.53: yapay zek\xc3\xa2 denetimi ----------------\nclass YzAyar(BaseModel):\n    anahtar: str = ""          # bo\xc5\x9f: de\xc4\x9fi\xc5\x9fmez\n    acik: bool | None = None\n    seslendirme_otomatik: bool | None = None\n    sil: bool = False          # anahtar\xc4\xb1 sil\n\n\n@app.get("/api/yz")\ndef yz_durum():\n    return yz.ozet()\n\n\n@app.post("/api/yz")\ndef yz_ayar(a: YzAyar):\n    kw = {}\n    anahtar = re.sub(r"\\s+", "", a.anahtar or "")   # kopyalarken araya giren bo\xc5\x9fluk/sat\xc4\xb1r sonu\n    if anahtar:\n        if not re.fullmatch(r"[A-Za-z0-9_.\\-]{20,200}", anahtar):\n            raise HTTPException(400, f"Bu bir Google API anahtar\xc4\xb1na benzemiyor ({len(anahtar)} karakter)")\n        kw["anahtar"] = anahtar\n    if a.sil:\n        kw["anahtar"] = ""\n    if a.acik is not None:\n        kw["acik"] = a.acik\n    if a.seslendirme_otomatik is not None:\n        kw["seslendirme_otomatik"] = a.seslendirme_otomatik\n    yz.ayar_yaz(**kw)\n    return yz.ozet()\n\n\n@app.post("/api/yz/dene")\ndef yz_dene():\n    if not yz.ayarlar().get("anahtar"):\n        raise HTTPException(400, "Anahtar kay\xc4\xb1tl\xc4\xb1 de\xc4\x9fil")\n    return yz.dene()\n\n\n@app.post("/api/kitaplar/{kid}/denetim")\ndef denetim_baslat(kid: str):\n    """Kitab\xc4\xb1 (yeniden) yapay zek\xc3\xa2yla denetler; bitince Osmanl\xc4\xb1ca ve \xc3\xa7\xc4\xb1kt\xc4\xb1lar yenilenir. Sakl\xc4\xb1 cevaplar yeniden sorulmaz."""\n    kit = _kitap(kid)\n    if kit["kunye"].get("asil_dil") != "tr":\n        raise HTTPException(409, "Denetim yaln\xc4\xb1z T\xc3\xbcrk\xc3\xa7e kitaplarda")\n    if not yz.ayarlar().get("anahtar") and not os.environ.get("STUDYO_YZ_SAHTE"):\n        raise HTTPException(400, "\xc3\x96nce Gemini anahtar\xc4\xb1n\xc4\xb1 kaydet (Yapay zek\xc3\xa2 ayar\xc4\xb1)")\n    d = depo.durum_oku(kid)\n    if d.get("asama") not in ("haz\xc4\xb1r", "hata"):\n        raise HTTPException(409, "Kitab\xc4\xb1n i\xc5\x9fi s\xc3\xbcr\xc3\xbcyor; bitince dene")\n    depo.is_ekle("denetim", kid, "elle")\n    return {"ok": True}\n\n\n@app.get("/api/kitaplar/{kid}/denetim_rapor")\ndef denetim_raporu(kid: str):\n    yol = os.path.join(depo.klasor(kid), "denetim.txt")\n    if not os.path.exists(yol):\n        raise HTTPException(404, "Denetim raporu yok")\n    return Response(open(yol, encoding="utf-8").read(), media_type="text/plain; charset=utf-8")\n\n\n# ---------------- Okuma ve d\xc3\xbczeltme ----------------\n@app.get("/oku/{kid}", response_class=HTMLResponse)\ndef oku_sayfasi(kid: str):\n    return open(os.path.join(STATIK, "oku.html"), encoding="utf-8").read()\n\n\ndef _okuma_dili(kit):\n    d = K.diller(kit)\n    return "tr" if "tr" in d else (d[0] if d else kit["kunye"].get("asil_dil", "tr"))\n\n\n@app.get("/api/kitaplar/{kid}/oku")\ndef oku_bilgi(kid: str):\n    kit = _kitap(kid)\n    yapi = epub.bolum_yapisi(kit, _okuma_dili(kit))\n    d = depo.durum_oku(kid)\n    return {"kimlik": kid, "kunye": kit["kunye"], "diller": K.diller(kit),\n            "bolumler": [{"no": i, "etiket": b["etiket"], "alt": b["alt"], "blok": len(b["bloklar"])} for i, b in enumerate(yapi)],\n            "konum": d.get("konum") or {"bolum": 0, "blok": None}, "asama": d.get("asama")}\n\n\ndef _blok_ozeti(b):\n    sayfa = next((s["no"] for s in b.get("sayfalar", [])), None)\n    return {"id": b["id"], "tur": b["tur"], "seviye": b.get("seviye"), "metin": b["metin"], "silindi": bool(b.get("silindi")),\n            "elle": b.get("elle") or {}, "gecmis": len(b.get("gecmis", [])), "sayfa": sayfa}\n\n\n@app.get("/api/kitaplar/{kid}/bolum/{no}")\ndef oku_bolum(kid: str, no: int):\n    kit = _kitap(kid)\n    yapi = epub.bolum_yapisi(kit, _okuma_dili(kit))\n    if not 0 <= no < len(yapi):\n        raise HTTPException(404, "B\xc3\xb6yle bir b\xc3\xb6l\xc3\xbcm yok")\n    ids = set(yapi[no]["bloklar"])\n    bloklar = [_blok_ozeti(b) for b in kit["bloklar"] if b["id"] in ids]\n    atif = set()\n    for b in bloklar:\n        for t in b["metin"].values():\n            atif |= set(K.NOT_ISARETI.findall(t or ""))\n    notlar = {g: n["metin"] for g, n in kit.get("dipnotlar", {}).items() if g in atif}\n    sira = {g: i + 1 for i, g in enumerate(kit.get("dipnotlar", {}))}\n    return {"no": no, "etiket": yapi[no]["etiket"], "bloklar": bloklar, "dipnotlar": notlar,\n            "not_no": {g: sira[g] for g in notlar}, "toplam": len(yapi)}\n\n\nclass BlokDegisiklik(BaseModel):\n    dil: str | None = None\n    metin: str | None = None\n    tur: str | None = None\n    seviye: int | None = None\n    silindi: bool | None = None\n\n\ndef _duzenle(kid, islem):\n    """kitap.json\'u kilit alt\xc4\xb1nda y\xc3\xbckle-de\xc4\x9fi\xc5\x9ftir-kaydet; sonra EPUB\'lar\xc4\xb1 yeniden \xc3\xbcretmeyi kuyru\xc4\x9fa koy."""\n    kilit = depo.kitap_kilidi(kid)\n    if not kilit.acquire(timeout=3):\n        raise HTTPException(409, "Kitap \xc5\x9fu an arka planda i\xc5\x9fleniyor; biraz sonra tekrar dene")\n    try:\n        kit = _kitap(kid)\n        sonuc = islem(kit)\n        K.kaydet(kit, depo.kitap_yolu(kid))\n    finally:\n        kilit.release()\n    depo.is_ekle("epub", kid, tur="epub")\n    return sonuc\n\n\n@app.patch("/api/kitaplar/{kid}/blok/{bid}")\ndef blok_duzelt(kid: str, bid: str, g: BlokDegisiklik):\n    uyari = []\n\n    def islem(kit):\n        try:\n            b = K.blok_bul(kit, bid)\n        except KeyError:\n            raise HTTPException(404, "B\xc3\xb6yle bir paragraf yok")\n        if g.metin is not None:\n            dil = g.dil or "tr"\n            yeni = " ".join(g.metin.split())\n            if not yeni:\n                raise HTTPException(400, "Metin bo\xc5\x9f olamaz; sat\xc4\xb1r\xc4\xb1 kald\xc4\xb1rmak i\xc3\xa7in \'Sil\'i kullan")\n            eski = b["metin"].get(dil, "")\n            if sorted(K.NOT_ISARETI.findall(eski)) != sorted(K.NOT_ISARETI.findall(yeni)):\n                raise HTTPException(400, "Dipnot i\xc5\x9faretleri ({{n\xe2\x80\xa6}}) de\xc4\x9fi\xc5\x9ftirilmemeli; metni i\xc5\x9faretlere dokunmadan d\xc3\xbczelt")\n            if K.duzelt(kit, bid, dil, yeni) and dil == "tr" and b["metin"].get("osm") is not None \\\n                    and not b.get("elle", {}).get("osm"):\n                try:  # T\xc3\xbcrk\xc3\xa7e d\xc3\xbczeldi: Osmanl\xc4\xb1cas\xc4\xb1 da yenilenir (elle d\xc3\xbczeltilmi\xc5\x9f Osmanl\xc4\xb1ca korunur)\n                    osm_eski = b["metin"]["osm"]\n                    b["metin"]["osm"] = osmanlica.blok_cevir(yeni)\n                    b["gecmis"][-1]["osm_eski"] = osm_eski  # "Geri al" Osmanl\xc4\xb1cay\xc4\xb1 da eski h\xc3\xa2line d\xc3\xb6nd\xc3\xbcrs\xc3\xbcn\n                except Exception as e:\n                    uyari.append(f"Osmanl\xc4\xb1cas\xc4\xb1 yenilenemedi ({type(e).__name__}); T\xc3\xbcrk\xc3\xa7e kaydedildi")\n        if g.tur is not None:\n            try:\n                K.tur_degistir(kit, bid, g.tur, g.seviye)\n            except ValueError as e:\n                raise HTTPException(400, str(e))\n        if g.silindi is not None:\n            K.sil(kit, bid, g.silindi)\n        return _blok_ozeti(K.blok_bul(kit, bid))\n    blok = _duzenle(kid, islem)\n    return {"blok": blok, "uyari": uyari}\n\n\n@app.post("/api/kitaplar/{kid}/blok/{bid}/geri")\ndef blok_geri_al(kid: str, bid: str):\n    def islem(kit):\n        try:\n            if not K.geri_al(kit, bid):\n                raise HTTPException(400, "Geri al\xc4\xb1nacak bir de\xc4\x9fi\xc5\x9fiklik yok")\n        except KeyError:\n            raise HTTPException(404, "B\xc3\xb6yle bir paragraf yok")\n        return _blok_ozeti(K.blok_bul(kit, bid))\n    return {"blok": _duzenle(kid, islem)}\n\n\nclass Konum(BaseModel):\n    bolum: int\n    blok: str | None = None\n\n\n@app.put("/api/kitaplar/{kid}/konum")\ndef konum_kaydet(kid: str, k: Konum):\n    if not depo.durum_oku(kid):\n        raise HTTPException(404, "B\xc3\xb6yle bir kitap yok")\n    depo.durum_yaz(kid, konum={"bolum": k.bolum, "blok": k.blok})\n    return {"ok": True}\n\n\n@app.get("/favicon.ico")\ndef favicon():\n    return Response(status_code=204)\n', 'tests/test_0560.py': b'"""0.5.60: (1) g\xc3\xbcnl\xc3\xbck s\xc4\xb1n\xc4\xb1r y\xc3\xbcz\xc3\xbcnden bekleyen denetim yeniden ba\xc5\x9flatmada kaybolmaz (a\xc5\x9famas\xc4\xb1 "haz\xc4\xb1r" g\xc3\xb6r\xc3\xbcnse de);\n(2) sesi olmayan par\xc3\xa7a seslendirme EPUB\'unu d\xc3\xbc\xc5\x9f\xc3\xbcrmez."""\nimport json, os, sys, tempfile, time, zipfile\nos.environ["DATA_DIR"] = tempfile.mkdtemp(prefix="t0560-")\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\nhata = []\n\n# (2) bo\xc5\x9f par\xc3\xa7a\nfrom app.worker import parts_to_epub  # noqa: E402\nout = os.path.join(os.environ["DATA_DIR"], "s.epub")\ntry:\n    parts_to_epub([{"tr": "Ba\xc5\x9fl\xc4\xb1k\\nBir c\xc3\xbcmle."}, {"tr": "  \\n"}, {"tr": "\xc4\xb0kinci\\nBa\xc5\x9fka c\xc3\xbcmle."}], "Deneme", out)\n    adlar = zipfile.ZipFile(out).namelist()\n    if not any(a.endswith("b0001.xhtml") for a in adlar) or not any(a.endswith("b0003.xhtml") for a in adlar):\n        hata.append(f"b\xc3\xb6l\xc3\xbcmler eksik: {adlar}")\nexcept Exception as e:\n    hata.append(f"bo\xc5\x9f par\xc3\xa7a EPUB\'u d\xc3\xbc\xc5\x9f\xc3\xbcrd\xc3\xbc: {type(e).__name__}: {e}")\n\n# (1) bekleyen denetim\nfrom kutuphane import depo  # noqa: E402\nkid = "k" + "0" * 11\nos.makedirs(depo.klasor(kid), exist_ok=True)\neklenen = []\ndepo.is_ekle = lambda *a, **k: eklenen.append(a)\ndepo.durum_yaz(kid, asama="haz\xc4\xb1r", denetim={"durum": "bekliyor", "devam": int(time.time()) - 10})\ndepo._bekleyen_denetim({"kimlik": kid, "asama": "haz\xc4\xb1r"})\ntime.sleep(6)\nif ("denetim", kid, None) not in eklenen:\n    hata.append(f"bekleyen denetim s\xc4\xb1raya girmedi: {eklenen}")\neklenen.clear()\ndepo.durum_yaz(kid, denetim={"durum": "hazir"})\ndepo._bekleyen_denetim({"kimlik": kid, "asama": "haz\xc4\xb1r"})\ntime.sleep(6)\nif eklenen:\n    hata.append("bitmi\xc5\x9f denetim yeniden s\xc4\xb1raya girdi")\nprint("\\n".join(hata) or "test_0560: hepsi ge\xc3\xa7ti")\nsys.exit(1 if hata else 0)\n'}
md5 = lambda b: hashlib.md5(b).hexdigest()
for f, icerik in YENI.items():
    var = open(f, "rb").read() if os.path.exists(f) else None
    if var is not None and md5(var) == md5(icerik):
        continue
    if f in ESKI and (var is None or md5(var) != ESKI[f]):
        sys.exit(f"DUR: {f} beklenen 0.5.59 dosyası değil (md5 {md5(var) if var else 'yok'}). Hiçbir şey değiştirilmedi.")
for f, icerik in YENI.items():
    open(f, "wb").write(icerik)
    print("yazıldı:", f, md5(icerik))
print("0.5.60 yaması tamam.")
